/// Revalidate the exact Checker-owned ResultBranchV3 source receipt against
/// executable MIR before a backend adapter consumes the ordinary Map
/// owned-get New/Set Result instructions.  This remains deliberately scoped
/// to the typed owned-get island: the route receipt alone does not authorize
/// the synthetic Result carrier or its branch-local root ownership.
pub fn validate_ordinary_map_owned_get_result_branch_v3_mir_route(
    checked: &crate::core::CheckedProgram,
    program: &reference::MirProgram,
) -> Result<CanonicalMirRouteReceipt, String> {
    use crate::core::OrdinaryMapOwnedGetI32StringV1ActionKind as Action;
    use crate::core::OrdinaryMapOwnedGetI32StringV1CfgProfileVersion as Profile;

    if program.purpose() != reference::MirProgramPurpose::Executable {
        return Err("ordinary Map owned-get ResultBranchV3 route requires executable MIR".into());
    }

    let mut checked_owners = BTreeSet::new();
    for (owner, callable) in checked.callables() {
        let Some(source_receipt) = callable
            .resources
            .ordinary_map_owned_get_i32_string_v1_cfg_receipt
            .as_ref()
            .filter(|receipt| receipt.profile_version == Profile::ResultBranchV3)
        else {
            continue;
        };
        if source_receipt.owner != *owner || source_receipt.result_branches.is_empty() {
            return Err(format!(
                "CheckedProgram owned-get ResultBranchV3 receipt for '{}' has an invalid owner or no branch evidence",
                owner.0
            ));
        }
        let function = program.functions().get(owner).ok_or_else(|| {
            format!(
                "owned-get ResultBranchV3 MIR route is missing receipted function '{}'",
                owner.0
            )
        })?;
        if function
            .ownership
            .ordinary_map_owned_get_result_branch_v3_receipt()
            != Some(source_receipt)
        {
            return Err(format!(
                "owned-get ResultBranchV3 MIR receipt for '{}' differs from its CheckedProgram source receipt",
                owner.0
            ));
        }
        function.validate().map_err(|errors| {
            format!(
                "owned-get ResultBranchV3 MIR validation failed for '{}': {errors:?}",
                owner.0
            )
        })?;
        for branch in &source_receipt.result_branches {
            if matches!(branch.kind, Action::New | Action::Set) {
                program
                    .type_catalog()
                    .validate_ordinary_map_owned_get_i32_string_v1_root_result(
                        &types::ordinary_map_owned_get_i32_string_v1_root_result_type_id(),
                        &branch.result_type,
                    )
                    .map_err(|message| {
                        format!(
                            "owned-get ResultBranchV3 synthetic Result TypeDesc rejected for '{}': {message}",
                            owner.0
                        )
                    })?;
            }
        }
        checked_owners.insert(owner.clone());
    }

    if checked_owners.is_empty() {
        return Err(
            "CheckedProgram has no exact ordinary Map owned-get ResultBranchV3 receipt".into(),
        );
    }

    for (owner, function) in program.functions() {
        if let Some(mir_receipt) = function
            .ownership
            .ordinary_map_owned_get_result_branch_v3_receipt()
        {
            if !checked_owners.contains(owner)
                || checked.callable(owner).and_then(|callable| {
                    callable
                        .resources
                        .ordinary_map_owned_get_i32_string_v1_cfg_receipt
                        .as_ref()
                }) != Some(mir_receipt)
            {
                return Err(format!(
                    "MIR owned-get ResultBranchV3 receipt for '{}' has no identical CheckedProgram source authority",
                    owner.0
                ));
            }
        }
    }

    let route = program.route_receipt(ORDINARY_MAP_OWNED_GET_I32_STRING_V1_ISLAND);
    route.validate_against_program(program)?;
    if route.profile != ORDINARY_MAP_OWNED_GET_I32_STRING_V1_ISLAND {
        return Err(
            "owned-get ResultBranchV3 route receipt has the wrong execution profile".into(),
        );
    }
    Ok(route)
}

/// Stable owner identity shared by resolved transition bodies, transition
/// contracts, and all backend adapters.
pub fn transition_owner_from_id(transition: &crate::core::TransitionId) -> NodeId {
    NodeId(format!(
        "transition:{}::{}::{}",
        transition.flow.0, transition.event, transition.source.name
    ))
}

macro_rules! mir_id {
    ($name:ident, $label:literal) => {
        #[derive(Debug, Clone, PartialEq, Eq, Hash, PartialOrd, Ord)]
        pub struct $name(String);

        impl $name {
            pub fn new(value: impl Into<String>) -> Result<Self, MirIdError> {
                let value = value.into();
                if value.trim().is_empty() {
                    return Err(MirIdError {
                        kind: $label,
                        value,
                    });
                }
                Ok(Self(value))
            }

            pub fn as_str(&self) -> &str {
                &self.0
            }
        }

        impl fmt::Display for $name {
            fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
                formatter.write_str(&self.0)
            }
        }
    };
}

mir_id!(MirBlockId, "block");
mir_id!(MirEdgeId, "edge");
mir_id!(MirValueId, "value");
mir_id!(MirInstructionId, "instruction");
mir_id!(MirInstanceId, "instance");

impl MirInstanceId {
    /// Stable identity for one checker-selected concrete generic instance.
    /// The type arguments are canonical `ResolvedTypeId`s, never source names
    /// or backend ABI spellings.
    pub fn for_template(
        template: &NodeId,
        arguments: &[ResolvedTypeId],
    ) -> Result<Self, MirIdError> {
        let mut identity = format!("instance:{}<", template.0);
        for (index, argument) in arguments.iter().enumerate() {
            if index != 0 {
                identity.push(',');
            }
            identity.push_str(argument.as_str());
        }
        identity.push('>');
        Self::new(identity)
    }
}

/// Checker-selected concrete generic instantiation recorded in canonical MIR.
/// The executable function referenced by `function` is already specialized;
/// the table keeps the template identity and argument proof attached so no
/// backend has to rediscover monomorphization from a callee name.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MirInstance {
    pub id: MirInstanceId,
    pub template: NodeId,
    pub arguments: Vec<ResolvedTypeId>,
    pub function: NodeId,
    pub contract: MirGenericInstanceContract,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MirIdError {
    pub kind: &'static str,
    pub value: String,
}

impl fmt::Display for MirIdError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(formatter, "{} identity must not be empty", self.kind)
    }
}

impl std::error::Error for MirIdError {}

/// A value available to a MIR instruction or block parameter.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MirValue {
    pub id: MirValueId,
    pub ty: ResolvedTypeId,
}

/// Block parameters are the canonical join-value form; consumers must not
/// invent a second phi representation.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MirBlockParameter {
    pub value: MirValueId,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum MirProjection {
    /// Checker-owned stable field identity.  A display name is deliberately
    /// not part of MIR; consumers resolve it through the TypeDesc layout.
    Field(NodeId),
    Tuple(usize),
    Index(MirValueId),
    Dereference,
    /// Read through a checker-materialized aggregate path without consuming
    /// any intermediate value. The embedded TypeDesc receipt is mandatory
    /// and the final result is restricted to Copy ownership.
    ReadPath(types::MirReadProjectionContract),
}

impl MirProjection {
    /// Stable spelling for contract identity text. Projection variants carry
    /// checker-owned IDs; consumers must not derive their meaning from a
    /// backend aggregate or from Rust's debug formatter.
    pub(crate) fn canonical_text(&self) -> String {
        match self {
            Self::Field(field) => format!("field({})", field.0),
            Self::Tuple(index) => format!("tuple({index})"),
            Self::Index(value) => format!("index({})", value.as_str()),
            Self::Dereference => "deref".into(),
            Self::ReadPath(receipt) => {
                let mut text = format!(
                    "read_path({}->{}, steps=[",
                    receipt.source_ty.as_str(),
                    receipt.result_ty.as_str()
                );
                for (index, step) in receipt.steps.iter().enumerate() {
                    if index != 0 {
                        text.push(';');
                    }
                    let _ = write!(
                        text,
                        "{}>{}:",
                        step.base_ty.as_str(),
                        step.result_ty.as_str()
                    );
                    match &step.projection {
                        types::MirReadProjectionKind::Field(field) => {
                            let _ = write!(text, "field({})", field.0);
                        }
                        types::MirReadProjectionKind::Tuple(index) => {
                            let _ = write!(text, "tuple({index})");
                        }
                    }
                }
                text.push_str("])");
                text
            }
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum MirAggregateKind {
    Tuple,
    Record {
        nominal: NominalTypeId,
        /// Stable checker field identities in the same order as `fields` in
        /// [`MirInstructionKind::Construct`].
        fields: Vec<NodeId>,
    },
}

/// Closed semantic operations for the first Set production island. The
/// receiver and result ownership rules live in TypeDesc; consumers only map
/// this enum to their physical runtime operation.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum MirSetOperation {
    Size,
    IsEmpty,
    Contains,
    Insert,
    Remove,
    /// Kept explicit so the adapter cannot accidentally treat `to_list` as a
    /// generic builtin before its List/result ownership contract is ready.
    ToList,
}

/// Closed operations over the canonical scalar List production island.
/// `Len` borrows the source and returns a Copy scalar; `Reverse` borrows the
/// source while materializing a fresh List through the List Clone glue;
/// `Concat` consumes both List inputs and materializes a fresh result. The
/// operation identity is part of the MIR contract so a consumer cannot
/// silently change a borrow into a move or drop one side of a double-input
/// ownership transfer.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum MirListOperation {
    Len,
    Reverse,
    Concat,
}

/// Read-only predicates over a checker-owned Option/Result discriminant.
/// The source is borrowed; the TypeDesc receipt fixes the family, variant
/// identity, and discriminant before a backend reads a physical tag.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum MirVariantPredicate {
    IsSome,
    IsNone,
    IsOk,
    IsErr,
}

/// Effect boundary carried by a materialized Flow transition contract.  The
/// first production island admits only a local silent self-loop; boundary
/// effects stay explicit so no consumer can accidentally erase epoch,
/// mailbox, FFI, or failure semantics.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum MirTransitionEffect {
    SilentLocal,
    /// A local transition whose body may return `Err((source, error))`. The
    /// source state is consumed into the failure value, so retry callers can
    /// only use the returned source once.
    RecoverableLocal,
    /// A synchronous cross-state transition whose body may return
    /// `Err((source, error))`. The state boundary is retained as an explicit
    /// effect fact; it is not silently reclassified as a local self-loop.
    RecoverableBoundary,
    Boundary,
}

impl MirTransitionEffect {
    pub const fn is_recoverable(self) -> bool {
        matches!(self, Self::RecoverableLocal | Self::RecoverableBoundary)
    }

    /// Stable spelling used by canonical identity text. This must stay
    /// independent of Rust's `Debug` representation so enum layout changes do
    /// not silently rewrite route receipt digests.
    pub const fn canonical_text(self) -> &'static str {
        match self {
            Self::SilentLocal => "silent_local",
            Self::RecoverableLocal => "recoverable_local",
            Self::RecoverableBoundary => "recoverable_boundary",
            Self::Boundary => "boundary",
        }
    }
}

/// Validate the complete identity carried by a Flow Boundary effect receipt.
/// This is shared by MIR admission and all four consumers so a receipt cannot
/// become a backend-local permission to call an otherwise unsupported target.
/// The checker-owned multi-target union shape: the transition result is a
/// FlowStateSet materialized as a closed Enum whose variants are exactly the
/// contract's target states (matched by state identity — the union orders
/// variants name-sorted while the contract keeps declaration order). Only
/// this proven shape may carry more than one target; every other
/// multi-target spelling stays fail-closed.
pub(crate) fn multi_target_union_shape(
    contract: &MirTransitionContract,
    type_catalog: &types::MirTypeCatalog,
) -> bool {
    contract.targets.len() > 1
        && contract.failure.is_none()
        && !contract.is_fallback
        && !contract.is_ffi_pinned
        && type_catalog
            .get(&contract.result)
            .is_some_and(|descriptor| match &descriptor.layout {
                types::MirLayout::Enum { variants, .. } => {
                    variants.len() == contract.targets.len()
                        && contract.targets.iter().all(|target| {
                            type_catalog.get(target).is_some_and(|target_desc| {
                                let (state_name, fields) = match &target_desc.layout {
                                    types::MirLayout::Record { nominal, fields } => {
                                        let name = nominal
                                            .as_str()
                                            .rsplit_once("::")
                                            .map(|(_, name)| name)
                                            .unwrap_or(nominal.as_str());
                                        (name, fields)
                                    }
                                    _ => return false,
                                };
                                variants
                                    .iter()
                                    .filter(|variant| variant.name == state_name)
                                    .count()
                                    == 1
                                    && variants
                                        .iter()
                                        .find(|variant| variant.name == state_name)
                                        .is_some_and(|variant| {
                                            fields.len() == variant.fields.len()
                                                && fields.iter().zip(&variant.fields).all(
                                                    |(field, payload)| {
                                                        field.id == payload.id
                                                            && field.name == payload.name
                                                            && field.ty == payload.ty
                                                    },
                                                )
                                        })
                            })
                        })
                }
                _ => false,
            })
}

pub(crate) fn validate_flow_effect_receipt(
    transition: &NodeId,
    contract: &MirTransitionContract,
    argument_types: &[ResolvedTypeId],
    result_ty: &ResolvedTypeId,
    receipt: Option<&types::MirFlowEffectReceipt>,
    type_catalog: &types::MirTypeCatalog,
) -> Result<(), String> {
    match (contract.effect, receipt) {
        (MirTransitionEffect::Boundary, Some(receipt)) => {
            if receipt.transition != *transition {
                return Err(
                    "Flow Boundary effect receipt transition identity disagrees with instruction"
                        .into(),
                );
            }
            if receipt.source != contract.source {
                return Err("Flow Boundary effect receipt source TypeDesc disagrees with transition contract".into());
            }
            if receipt.parameters != argument_types || receipt.parameters != contract.parameters {
                return Err("Flow Boundary effect receipt parameter TypeDesc identities disagree with transition contract".into());
            }
            if receipt.result != *result_ty || receipt.result != contract.result {
                return Err("Flow Boundary effect receipt result TypeDesc disagrees with transition contract".into());
            }
            let [target] = contract.targets.as_slice() else {
                // A multi-target union transition has no single target; the
                // receipt must name the union identity itself.
                if multi_target_union_shape(contract, type_catalog) {
                    if receipt.target != contract.result {
                        return Err("Flow Boundary effect receipt target identity disagrees with transition contract".into());
                    }
                    return Ok(());
                }
                return Err(
                    "Flow Boundary effect receipt target identity disagrees with transition contract"
                        .into(),
                );
            };
            if receipt.target != *target {
                return Err("Flow Boundary effect receipt target identity disagrees with transition contract".into());
            }
            Ok(())
        }
        (MirTransitionEffect::Boundary, None) => {
            Err("Boundary effect requires an explicit canonical effect receipt".into())
        }
        (_, Some(_)) => Err("Flow effect receipt is attached to a non-Boundary transition".into()),
        (_, None) => Ok(()),
    }
}

/// Checker-owned ABI/ownership/effect contract for a Flow transition.
/// `parameters` includes the consumed source state as its first entry.  The
/// transition instruction refers to `owner` rather than re-encoding a surface
/// Flow name, so all consumers use the same materialized identity.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MirTransitionContract {
    pub owner: NodeId,
    pub source: ResolvedTypeId,
    pub parameters: Vec<ResolvedTypeId>,
    pub result: ResolvedTypeId,
    pub targets: Vec<ResolvedTypeId>,
    pub failure: Option<ResolvedTypeId>,
    pub effect: MirTransitionEffect,
    pub is_fallback: bool,
    pub is_ffi_pinned: bool,
}

impl MirTransitionContract {
    pub fn canonical_text(&self) -> String {
        format!(
            "mir.transition {} {} [{}] -> {} targets [{}] failure {} fallback={} pinned={}\n",
            self.owner.0,
            self.effect.canonical_text(),
            self.parameters
                .iter()
                .map(|ty| ty.as_str())
                .collect::<Vec<_>>()
                .join(","),
            self.result.as_str(),
            self.targets
                .iter()
                .map(|ty| ty.as_str())
                .collect::<Vec<_>>()
                .join(","),
            self.failure
                .as_ref()
                .map(ResolvedTypeId::as_str)
                .unwrap_or("-"),
            self.is_fallback,
            self.is_ffi_pinned,
        )
    }
}

/// Closed proof carried by a materialized generic MIR instance. The instance
/// table is part of the canonical program, so consumers must not guess which
/// generic template family a specialized body belongs to from its symbol name
/// or physical ABI.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
pub enum MirGenericInstanceContract {
    ScalarIdentity,
    /// A Checker-proven `T, ... T -> T` callable whose body directly returns
    /// a selected parameter or binds that parameter to one immutable local
    /// and returns the local, specialized to a concrete Copy scalar. The
    /// arity and selected position are carried in the MIR receipt and the
    /// exact body shape is independently checked by every consumer.
    ScalarArgumentProjection {
        parameter_index: u32,
        parameter_count: u32,
    },
    /// The exact direct generic identity body specialized to the canonical
    /// managed-Any owner.  This remains separate from both scalar identity
    /// and arbitrary Any forwarding: its private Checker seal binds the
    /// template, instance key, type argument, owner values, and Clone/Drop
    /// instruction sequence.
    ManagedAnyIdentity,
    /// An exact callee-owned cleanup instance for a generic parameter that
    /// was specialized to ManagedAny before a guaranteed checked i32 trap.
    /// Only the two arithmetic trap bodies represented by this kind are
    /// materialized; this is not a general permission for Any-typed generic
    /// functions.
    ManagedAnyTrapCleanup {
        trap: MirManagedAnyTrapKind,
    },
    /// `identity<T>(T) -> T` specialized to the canonical move-owned String
    /// ABI.  This is separate from the Copy/flat-variant identity island so
    /// consumers cannot accidentally treat an owned handle as a no-op value.
    OwnedStringIdentity,
    ScalarSetFacade {
        operation: MirSetOperation,
    },
    /// A generic scalar List facade (`Len`, `Reverse`, or `Concat`) specialized to a
    /// concrete Copy scalar element. The executable body remains a canonical
    /// `Clone; ListOp; Return` shape for the read/clone operations; `Concat`
    /// carries two moved List inputs. This contract prevents consumers from
    /// treating an arbitrary generic List body as a trusted instance.
    ScalarListFacade {
        operation: MirListOperation,
    },
    /// A generic single-element List construction specialized to a concrete
    /// Copy scalar. The construction receipt is part of the instance
    /// contract so consumers cannot treat a generic List literal as an
    /// unchecked backend container.
    ScalarListConstruct {
        contract: types::MirListConstructContract,
    },
    /// A generic `first<T>(List<T>) -> T` read-only constant-index projection
    /// specialized to a concrete Copy scalar. The existing List-index receipt
    /// carries TypeDesc identities; the instance contract also fixes the
    /// checker-proven index literal so consumers cannot widen it to arbitrary
    /// dynamic projection semantics.
    ScalarListProjection {
        contract: types::MirListIndexProjectionContract,
        index_value: i64,
    },
    /// A generic one- or two-field record projection specialized to a
    /// concrete Copy-scalar field. Every field shares the same concrete
    /// scalar TypeDesc; the instance receipt fixes the nominal/field identity
    /// so consumers cannot infer a generic record ABI from names.
    ScalarRecordProjection {
        contract: types::MirRecordProjectionContract,
    },
    /// A generic flat Copy record update with a checker-proven set of scalar
    /// field overrides.  The update receipt fixes the source/result TypeDesc,
    /// nominal, full declaration arity, and every overlay field identity.
    ScalarRecordUpdate {
        contract: types::MirRecordUpdateContract,
    },
    /// A generic Move-owned two-field record update with one overwritten
    /// payload. The receipt proves Drop for the old slot and MoveOut for the
    /// new slot plus the residual field moved into the result.
    OwnedRecordUpdate {
        contract: types::MirRecordUpdateMoveContract,
    },
    /// A generic two-element tuple projection specialized to a concrete
    /// Copy-scalar element. The tuple receipt fixes the structural index and
    /// arity so consumers cannot infer a generic tuple ABI from a backend
    /// aggregate or runtime vector.
    ScalarTupleProjection {
        contract: types::MirTupleProjectionContract,
    },
    /// A generic one- or two-field record projection specialized to a managed
    /// move-owned payload (`String` or `List<Copy scalar>`). The executable
    /// body is a consuming `MoveProject`; the receipt fixes nominal/field
    /// identity and the TypeDesc proves any sibling is Copy, so consumers
    /// cannot silently clone a payload or infer ownership from the native/VM
    /// representation.
    OwnedRecordProjection {
        contract: types::MirRecordProjectionContract,
    },
    /// A generic record projection that moves one owned field and explicitly
    /// drops every non-Copy residual sibling.  This is deliberately separate
    /// from `OwnedRecordProjection`: its residual schedule is part of the
    /// canonical receipt, so consumers cannot silently discard an additional
    /// owned field or infer a partial-move policy from an aggregate handle.
    OwnedRecordProjectionDrop {
        contract: types::MirRecordMoveProjectionDropContract,
    },
    /// A generic `Option<T>.is_some()`/`is_none()` predicate specialized to a
    /// concrete Copy scalar payload. The predicate is read-only: the
    /// materialized body carries the same TypeDesc tag receipt consumed by
    /// the direct `VariantPredicate` node, so no backend may infer the
    /// variant ABI from a generic instance symbol or runtime tag.
    ScalarVariantPredicate {
        contract: types::MirVariantPredicateContract,
    },
    /// A generic `Option<T>.unwrap()` or `Result<T, T>`/`Result<T, i32>`
    /// payload projection specialized to a concrete Copy scalar, or the
    /// explicitly admitted move-owned `Option<string>`/`Option<List<Copy
    /// scalar>>`/`Result<string, i32>`/`Result<List<Copy scalar>, i32>` shape.
    /// The trap-bearing receipt is
    /// materialized after specialization so consumers cannot infer the
    /// variant ABI or ownership from the generic instance symbol.
    ScalarVariantProjection {
        contract: types::MirVariantProjectionTrapContract,
    },
    /// A generic `Option<T>.unwrap_or(T)`, `Result<T,T>.unwrap_or(T)` or
    /// `Result<T,i32>.unwrap_or(T)` total projection specialized to a concrete
    /// Copy scalar. The fallback receipt fixes both variant identities and the
    /// explicit fallback ABI so consumers cannot infer a branch from a
    /// physical aggregate.
    ScalarVariantProjectionFallback {
        contract: types::MirVariantProjectionFallbackContract,
    },
}

/// Exact guaranteed arithmetic traps whose generic callee cleanup is
/// checker-sealed for a ManagedAny parameter.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum MirManagedAnyTrapKind {
    DivisionByZeroI32,
    SignedOverflowI32,
}

impl MirManagedAnyTrapKind {
    pub const fn canonical_text(self) -> &'static str {
        match self {
            Self::DivisionByZeroI32 => "division_by_zero_i32",
            Self::SignedOverflowI32 => "signed_overflow_i32",
        }
    }
}

impl MirSetOperation {
    /// Stable spelling used by canonical instance identity text.  The
    /// semantic route digest must not inherit Rust's derived `Debug` format.
    pub const fn canonical_text(self) -> &'static str {
        match self {
            Self::Size => "size",
            Self::IsEmpty => "is_empty",
            Self::Contains => "contains",
            Self::Insert => "insert",
            Self::Remove => "remove",
            Self::ToList => "to_list",
        }
    }
}

impl MirListOperation {
    /// Stable spelling used by canonical instance identity text.
    pub const fn canonical_text(self) -> &'static str {
        match self {
            Self::Len => "len",
            Self::Reverse => "reverse",
            Self::Concat => "concat",
        }
    }
}

impl MirVariantPredicate {
    /// Stable spelling used by canonical instance identity text.
    pub const fn canonical_text(self) -> &'static str {
        match self {
            Self::IsSome => "is_some",
            Self::IsNone => "is_none",
            Self::IsOk => "is_ok",
            Self::IsErr => "is_err",
        }
    }
}

fn canonical_record_projection_contract(contract: &types::MirRecordProjectionContract) -> String {
    format!(
        "nominal={} field={} name={} index={} arity={} field_ty={}",
        contract.nominal.as_str(),
        contract.field.0,
        contract.name,
        contract.field_index,
        contract.arity,
        contract.field_ty.as_str()
    )
}

fn canonical_variant_projection_contract(contract: &types::MirVariantProjectionContract) -> String {
    format!(
        "nominal={} variant={} field={} index={} arity={} field_ty={} ownership={} move_out_glue={}",
        contract.nominal.as_str(),
        contract.variant.0,
        contract.field.0,
        contract.field_index,
        contract.arity,
        contract.field_ty.as_str(),
        contract.ownership.canonical_text(),
        contract.move_out_glue.canonical_text()
    )
}

fn canonical_instance_contract_text(contract: &MirGenericInstanceContract) -> String {
    match contract {
        MirGenericInstanceContract::ScalarIdentity => "scalar_identity".into(),
        MirGenericInstanceContract::ScalarArgumentProjection {
            parameter_index,
            parameter_count,
        } => format!("scalar_argument_projection index={parameter_index} arity={parameter_count}"),
        MirGenericInstanceContract::ManagedAnyIdentity => "managed_any_identity".into(),
        MirGenericInstanceContract::ManagedAnyTrapCleanup { trap } => {
            format!("managed_any_trap_cleanup trap={}", trap.canonical_text())
        }
        MirGenericInstanceContract::OwnedStringIdentity => "owned_string_identity".into(),
        MirGenericInstanceContract::ScalarSetFacade { operation } => {
            format!("scalar_set_facade operation={}", operation.canonical_text())
        }
        MirGenericInstanceContract::ScalarListFacade { operation } => {
            format!(
                "scalar_list_facade operation={}",
                operation.canonical_text()
            )
        }
        MirGenericInstanceContract::ScalarListConstruct { contract } => format!(
            "scalar_list_construct list_ty={} element_ty={} result_ty={} element_count={}",
            contract.list_ty.as_str(),
            contract.element_ty.as_str(),
            contract.result_ty.as_str(),
            contract.element_count
        ),
        MirGenericInstanceContract::ScalarListProjection {
            contract,
            index_value,
        } => format!(
            "scalar_list_projection list_ty={} element_ty={} index_ty={} result_ty={} mode={} index_value={}",
            contract.list_ty.as_str(),
            contract.element_ty.as_str(),
            contract.index_ty.as_str(),
            contract.result_ty.as_str(),
            match contract.mode {
                types::MirListIndexProjectionMode::CopyScalar => "copy_scalar",
                types::MirListIndexProjectionMode::CloneNestedList => "clone_nested_list",
            },
            index_value
        ),
        MirGenericInstanceContract::ScalarRecordProjection { contract } => format!(
            "scalar_record_projection {}",
            canonical_record_projection_contract(contract)
        ),
        MirGenericInstanceContract::OwnedRecordProjection { contract } => format!(
            "owned_record_projection {}",
            canonical_record_projection_contract(contract)
        ),
        MirGenericInstanceContract::ScalarRecordUpdate { contract } => {
            let fields = contract
                .fields
                .iter()
                .map(canonical_record_projection_contract)
                .collect::<Vec<_>>()
                .join(";");
            format!(
                "scalar_record_update source_ty={} result_ty={} nominal={} arity={} fields=[{}]",
                contract.source_ty.as_str(),
                contract.result_ty.as_str(),
                contract.nominal.as_str(),
                contract.arity,
                fields
            )
        }
        MirGenericInstanceContract::OwnedRecordUpdate { contract } => {
            let updates = contract
                .updates
                .iter()
                .map(|update| {
                    format!(
                        "projection=({}) old_drop={} new_move={}",
                        canonical_record_projection_contract(&update.projection),
                        update.old_drop.canonical_text(),
                        update.new_move.canonical_text()
                    )
                })
                .collect::<Vec<_>>()
                .join(";");
            let residual = contract
                .residual
                .iter()
                .map(|field| {
                    format!(
                        "id={} name={} index={} ty={} glue={}",
                        field.id.0,
                        field.name,
                        field.index,
                        field.ty.as_str(),
                        field.glue.canonical_text()
                    )
                })
                .collect::<Vec<_>>()
                .join(";");
            format!(
                "owned_record_update source_ty={} result_ty={} nominal={} arity={} updates=[{}] residual=[{}]",
                contract.source_ty.as_str(),
                contract.result_ty.as_str(),
                contract.nominal.as_str(),
                contract.arity,
                updates,
                residual
            )
        }
        MirGenericInstanceContract::ScalarTupleProjection { contract } => format!(
            "scalar_tuple_projection tuple_ty={} field_index={} arity={} field_ty={}",
            contract.tuple_ty.as_str(),
            contract.field_index,
            contract.arity,
            contract.field_ty.as_str()
        ),
        MirGenericInstanceContract::OwnedRecordProjectionDrop { contract } => {
            let residual = contract
                .residual
                .iter()
                .map(|field| {
                    format!(
                        "id={} name={} index={} ty={} glue={}",
                        field.id.0,
                        field.name,
                        field.index,
                        field.ty.as_str(),
                        field.glue.canonical_text()
                    )
                })
                .collect::<Vec<_>>()
                .join(";");
            format!(
                "owned_record_projection_drop source_ty={} result_ty={} projection=({}) residual=[{}]",
                contract.source_ty.as_str(),
                contract.result_ty.as_str(),
                canonical_record_projection_contract(&contract.projection),
                residual
            )
        }
        MirGenericInstanceContract::ScalarVariantPredicate { contract } => format!(
            "scalar_variant_predicate variant_ty={} result_ty={} nominal={} variant={} variant_name={} alternate_variant={} alternate_variant_name={} predicate={} discriminant={}",
            contract.variant_ty.as_str(),
            contract.result_ty.as_str(),
            contract.nominal.as_str(),
            contract.variant.0,
            contract.variant_name,
            contract.alternate_variant.0,
            contract.alternate_variant_name,
            contract.predicate.canonical_text(),
            contract.discriminant
        ),
        MirGenericInstanceContract::ScalarVariantProjection { contract } => format!(
            "scalar_variant_projection source_ty={} result_ty={} projection=({}) variant_name={} discriminant={} trap_code={}",
            contract.source_ty.as_str(),
            contract.result_ty.as_str(),
            canonical_variant_projection_contract(&contract.projection),
            contract.variant_name,
            contract.discriminant,
            contract.trap_code
        ),
        MirGenericInstanceContract::ScalarVariantProjectionFallback { contract } => format!(
            "scalar_variant_projection_fallback source_ty={} result_ty={} fallback_ty={} projection=({}) variant_name={} discriminant={} fallback_variant={} fallback_variant_name={} fallback_discriminant={} fallback_arity={}",
            contract.source_ty.as_str(),
            contract.result_ty.as_str(),
            contract.fallback_ty.as_str(),
            canonical_variant_projection_contract(&contract.projection),
            contract.variant_name,
            contract.discriminant,
            contract.fallback_variant.0,
            contract.fallback_variant_name,
            contract.fallback_discriminant,
            contract.fallback_arity
        ),
    }
}

/// Operations with explicit value and ownership boundaries. The MIR validator
/// checks their TypeDesc/glue contract before any backend; effect-bearing
/// operations remain fail-closed until their own effect summary is materialized.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum MirInstructionKind {
    /// Explicit checker-receipted state and mailbox boundary.
    Actor {
        operation: MirActorOperation,
    },
    /// Bind a Checker-identified source closure local to a static callable
    /// identity. V1 has no runtime environment or function pointer: the
    /// whole-program closure receipt binds this local and its function value
    /// to one exact nested callable owner.
    ClosureBind {
        closure_local: ResolvedLocalId,
        function_value: MirValueId,
        callee: NodeId,
        abi: MirClosureCallableAbiV1,
    },
    /// Invoke a statically resolved closure target through an independent MIR
    /// operation. Consumers must preserve direct-call result, trap, and
    /// ownership behavior after shared receipt validation.
    ClosureInvoke {
        result: Option<MirValueId>,
        closure_local: ResolvedLocalId,
        function_value: MirValueId,
        callee: NodeId,
        type_arguments: Vec<ResolvedTypeId>,
        arguments: Vec<MirValueId>,
        abi: MirClosureCallableAbiV1,
    },
    /// Checker-authorized construction of an opaque runtime Map table root.
    MapRootNew {
        result: MirValueId,
    },
    /// Persistent update: consumes `source` and produces a distinct root.
    MapRootSet {
        result: MirValueId,
        source: MirValueId,
        key: String,
        value: MirValueId,
    },
    /// Consume one Checker-owned MapRoot and return its persistent update
    /// after removing the exact static key. The closed profile has no
    /// `get`/`values` escape, so removing an owned String can release it.
    MapRootRemove {
        result: MirValueId,
        source: MirValueId,
        key: String,
    },
    /// Borrowing size query. The result is the checker's i32 surface value.
    MapRootSize {
        result: MirValueId,
        root: MirValueId,
    },
    /// Borrowing static-key membership query. This reads only the Map key
    /// index and leaves the Checker-owned root live for later operations.
    MapRootContains {
        result: MirValueId,
        root: MirValueId,
        key: String,
    },
    /// Consume and release a Map table root.
    MapRootDrop {
        root: MirValueId,
    },
    /// Create an ordinary source-Map owner root for the independent
    /// persistent i32/String lifecycle profile.
    OrdinaryMapOwnerLifecycleNew {
        result: MirValueId,
    },
    /// Persistent Set: borrow `source`, copy one typed payload and key, and
    /// create a distinct result root. The source remains observable.
    OrdinaryMapOwnerLifecycleSet {
        result: MirValueId,
        source: MirValueId,
        key: MirValueId,
        value: MirValueId,
    },
    /// Persistent Remove: borrow `source` and create a distinct root without
    /// `key`; the source remains observable.
    OrdinaryMapOwnerLifecycleRemove {
        result: MirValueId,
        source: MirValueId,
        key: MirValueId,
    },
    /// Borrowing size query on a live ordinary Map root.
    OrdinaryMapOwnerLifecycleSize {
        result: MirValueId,
        root: MirValueId,
    },
    /// Borrowing membership query with a typed dynamic String key.
    OrdinaryMapOwnerLifecycleContains {
        result: MirValueId,
        root: MirValueId,
        key: MirValueId,
    },
    /// Release exactly one owner root admitted by the ordinary Map profile.
    OrdinaryMapOwnerLifecycleDrop {
        root: MirValueId,
    },
    /// Borrow a lifecycle-v1 root and produce a detached, owned Mimi String
    /// containing its canonical JSON snapshot.
    OrdinaryMapOwnerLifecycleObserverToJson {
        result: MirValueId,
        root: MirValueId,
        callsite: NodeId,
    },
    /// Borrow a lifecycle-v1 root and print its canonical JSON snapshot,
    /// leaving the root live. The Unit result records the checked call.
    OrdinaryMapOwnerLifecycleObserverPrintln {
        result: MirValueId,
        root: MirValueId,
        callsite: NodeId,
    },
    /// Create an ordinary Map root for the independent typed owned-get v1
    /// profile.
    OrdinaryMapOwnedGetI32StringV1New {
        result: MirValueId,
    },
    /// Fallible owned-get V1 New lowered only under an exact Checker
    /// ResultBranchV3 receipt. The result has the canonical synthetic
    /// `Result<V1Root, i32>` envelope so `SwitchMove` transfers the Ok root.
    OrdinaryMapOwnedGetI32StringV1NewResult {
        result: MirValueId,
    },
    /// Persistent typed-profile Set: preserve the source root and create the
    /// distinct successor root in `result`.
    OrdinaryMapOwnedGetI32StringV1Set {
        result: MirValueId,
        source: MirValueId,
        key: MirValueId,
        value: MirValueId,
    },
    /// Fallible persistent owned-get V1 Set. The source root remains live on
    /// both outcomes; only Ok carries the fresh successor root.
    OrdinaryMapOwnedGetI32StringV1SetResult {
        result: MirValueId,
        source: MirValueId,
        key: MirValueId,
        value: MirValueId,
    },
    /// Persistent typed-profile Remove: preserve the source root and create
    /// the distinct successor root in `result`.
    OrdinaryMapOwnedGetI32StringV1Remove {
        result: MirValueId,
        source: MirValueId,
        key: MirValueId,
    },
    /// Read the size of one live typed-profile root.
    OrdinaryMapOwnedGetI32StringV1Size {
        result: MirValueId,
        root: MirValueId,
    },
    /// Test a dynamic String key against one live typed-profile root.
    OrdinaryMapOwnedGetI32StringV1Contains {
        result: MirValueId,
        root: MirValueId,
        key: MirValueId,
    },
    /// Return an owned `Result<i32, i32>` payload from a live typed-profile
    /// root, preserving the Map root itself.
    OrdinaryMapOwnedGetI32StringV1GetI32 {
        result: MirValueId,
        root: MirValueId,
        key: MirValueId,
    },
    /// Return an owned `Result<string, i32>` payload from a live
    /// typed-profile root, preserving the Map root itself.
    OrdinaryMapOwnedGetI32StringV1GetString {
        result: MirValueId,
        root: MirValueId,
        key: MirValueId,
    },
    /// Borrow the Map and publish a separately owned snapshot. Missing keys
    /// return (false, fresh owned I32 zero), never an unowned token.
    OrdinaryMapOwnedGetI32StringV1GetAny {
        result: MirValueId,
        root: MirValueId,
        key: MirValueId,
    },
    /// Borrow a live typed-profile root and return a move-owned canonical
    /// `List<ManagedAny>` snapshot. Each element is an independent owner;
    /// dropping the list releases those element tokens while preserving the
    /// source Map root.
    OrdinaryMapOwnedGetI32StringV1Values {
        result: MirValueId,
        root: MirValueId,
    },
    /// Clone/drop or borrowed checked unpack of a generation-bearing Any.
    ManagedAny {
        result: Option<MirValueId>,
        source: MirValueId,
        operation: MirManagedAnyOperation,
        contract: Option<MirManagedAnyContract>,
    },
    /// Release one live root admitted by the typed owned-get v1 profile.
    OrdinaryMapOwnedGetI32StringV1Drop {
        root: MirValueId,
    },
    /// Canonical ordinary Map/Any owner-v2 operations.  The checker receipt
    /// keeps the payload opaque; MIR only records the persistent root and
    /// scalar/dynamic operands.
    OrdinaryMapOwnedAnyV2New {
        result: MirValueId,
    },
    OrdinaryMapOwnedAnyV2Set {
        result: MirValueId,
        source: MirValueId,
        key: MirValueId,
        value: MirValueId,
    },
    /// Fallible, persistent ordinary Map/Any Set whose checked source result
    /// is `Result<Record, i32>`. Unlike bare-root Set, this returns an
    /// exhaustive Result carrier and leaves `source` live on both outcomes.
    OrdinaryMapOwnedAnyV2SetResult {
        result: MirValueId,
        source: MirValueId,
        key: MirValueId,
        value: MirValueId,
    },
    /// Branch-only fallible persistent Set for the closed ordinary Map/Any
    /// V2 payload profile. The result uses the canonical synthetic
    /// `Result<OrdinaryMapOwnedAnyV2, i32>` carrier. Unlike the i32-only
    /// `SetResult`, `value` keeps its concrete V2 Any payload TypeDesc so
    /// consumers must preserve the normal payload selection and clone ABI.
    /// This operation is valid only under the exact computed String-key
    /// owner-chain Result-branch receipt and its dedicated route proof.
    OrdinaryMapOwnedAnyV2SetAnyResult {
        result: MirValueId,
        source: MirValueId,
        key: MirValueId,
        value: MirValueId,
    },
    /// Borrow a live SetResult-lineage root and return a checked typed lookup
    /// as `Result<i32, i32>`. The source root remains owned by its caller on
    /// both outcomes; its exact lineage is sealed by the Set/Get receipt.
    OrdinaryMapOwnedAnyV2GetI32Result {
        result: MirValueId,
        root: MirValueId,
        key: MirValueId,
    },
    /// Persistent fallible Map Set that copies an exact owned String payload
    /// into the new root snapshot. The Checker source keeps the payload owner
    /// live until its explicit source-bound Drop after this operation.
    OrdinaryMapOwnedAnyV2SetStringResult {
        result: MirValueId,
        source: MirValueId,
        key: MirValueId,
        value: MirValueId,
    },
    /// Borrow the exact persistent Map root and return an independently
    /// owned `Result<String, i32>`. Ok payload projection is Move/OwnedString;
    /// the Checker receipt requires the source Map root to remain live until
    /// its branch-local Drop.
    OrdinaryMapOwnedAnyV2GetStringResult {
        result: MirValueId,
        root: MirValueId,
        key: MirValueId,
    },
    OrdinaryMapOwnedAnyV2Remove {
        result: MirValueId,
        source: MirValueId,
        key: MirValueId,
    },
    OrdinaryMapOwnedAnyV2Size {
        result: MirValueId,
        root: MirValueId,
    },
    OrdinaryMapOwnedAnyV2Contains {
        result: MirValueId,
        root: MirValueId,
        key: MirValueId,
    },
    /// Read one key from a live V2 root and produce an independent
    /// `(found, DynamicAny-owner)` result. The source root remains live.
    OrdinaryMapOwnedAnyV2GetAny {
        result: MirValueId,
        root: MirValueId,
        key: MirValueId,
    },
    /// Borrow one V2 root and produce `Result<(found, DynamicAny-owner), i32>`.
    /// Only owner-publication capacity is a recoverable `Err`; malformed ABI,
    /// stale roots, and descriptor/runtime contract violations remain traps.
    OrdinaryMapOwnedAnyV2GetAnyResult {
        result: MirValueId,
        root: MirValueId,
        key: MirValueId,
    },
    /// Borrow the DynamicAny payload field of one Checker-receipted GetAny
    /// pair and exact-clone it into the statically checked target TypeDesc.
    /// The pair remains the owner and must still be explicitly settled.
    OrdinaryMapOwnedAnyV2Unpack {
        result: MirValueId,
        pair: MirValueId,
        projection: NodeId,
    },
    /// Execute the exact `std::maps.get_or_default<i32>` callsite admitted by
    /// the independent Checker/MIR ownership bridge. `root` is borrowed and
    /// remains live; the operation replays the helper's GetAny, found-only
    /// checked i32 unpack, caller-provided default selection, and whole-pair
    /// settlement. The receipt binds every operand to its source argument.
    OrdinaryMapOwnedAnyV2GetOrDefaultI32 {
        result: MirValueId,
        root: MirValueId,
        key: MirValueId,
        default: MirValueId,
        callsite: NodeId,
        call_target: NodeId,
        type_argument: ResolvedTypeId,
    },
    /// Execute the exact `std::maps.get_or_default<String>` callsite admitted
    /// by the independent Checker/MIR ownership bridge. The Map root remains
    /// borrowed; the operation returns an owned String copy and consumes the
    /// literal default argument. The helper's i32-zero miss sentinel is never
    /// interpreted as String.
    OrdinaryMapOwnedAnyV2GetOrDefaultString {
        result: MirValueId,
        root: MirValueId,
        key: MirValueId,
        default: MirValueId,
        callsite: NodeId,
        call_target: NodeId,
        type_argument: ResolvedTypeId,
    },
    /// Borrow the exact field-1 payload of one source-receipted V2 GetAny
    /// pair for canonical println. The payload remains V2 and the pair is
    /// settled only by its later explicit whole-value Drop.
    OrdinaryMapOwnedAnyV2Println {
        result: MirValueId,
        pair: MirValueId,
        projection: NodeId,
    },
    /// Borrow one exact Checker-receipted index from an owned Values
    /// snapshot, then clone its selected DynamicAny payload into the
    /// statically selected target TypeDesc. The Values snapshot remains the
    /// owner of its element tokens and must still be explicitly settled.
    OrdinaryMapOwnedAnyV2ValuesUnpack {
        result: MirValueId,
        values: MirValueId,
        index: MirValueId,
        projection: NodeId,
    },
    /// Borrow a live V2 root and produce an independently owned, sorted
    /// `List<DynamicAny>` snapshot. The source root remains live; the result
    /// uses a Values-specific TypeDesc and settlement receipt.
    OrdinaryMapOwnedAnyV2Values {
        result: MirValueId,
        root: MirValueId,
    },
    /// Borrow a live V2 root and materialize its deterministic key-sorted
    /// `List<String>` snapshot. The returned list owns independent String
    /// payloads and is settled through the ordinary flat owned-String List
    /// glue; the source root remains live.
    OrdinaryMapOwnedAnyV2Keys {
        result: MirValueId,
        root: MirValueId,
    },
    /// Copy index zero from one exact Checker-receipted Keys snapshot into a
    /// fresh owned String. This opaque operation deliberately does not widen
    /// generic `List<String>` indexing.
    OrdinaryMapOwnedAnyV2KeysUnpack {
        result: MirValueId,
        keys: MirValueId,
        projection: NodeId,
    },
    /// Read the first user-supplied CLI argument as one owned Mimi String.
    /// This node is emitted only for the exact source-owned DynamicKeysGet
    /// profile; generic `args()` builtin lowering cannot authorize it.
    OrdinaryMapOwnedAnyV2DynamicArg0 {
        result: MirValueId,
        projection: NodeId,
    },
    OrdinaryMapOwnedAnyV2IsEmpty {
        result: MirValueId,
        root: MirValueId,
    },
    OrdinaryMapOwnedAnyV2Drop {
        root: MirValueId,
    },
    Const {
        result: MirValueId,
        literal: ResolvedLiteral,
    },
    Load {
        result: MirValueId,
        place: ResolvedPlace,
    },
    Copy {
        result: MirValueId,
        source: MirValueId,
    },
    Move {
        result: MirValueId,
        source: MirValueId,
    },
    Clone {
        result: MirValueId,
        source: MirValueId,
    },
    Drop {
        value: MirValueId,
    },
    Borrow {
        /// Checker-stable identity of the loan started by this operation.
        loan: NodeId,
        /// Resolved expression identity that starts the loan.
        point: NodeId,
        /// Checker place identity copied from the matching borrow-start action.
        checker_resource: Option<String>,
        /// Checker place display copied from the matching borrow-start action.
        checker_source: Option<String>,
        result: MirValueId,
        source: MirValueId,
        mutable: bool,
    },
    EndBorrow {
        borrow: MirValueId,
    },
    Project {
        result: MirValueId,
        base: MirValueId,
        projection: MirProjection,
        /// TypeDesc receipt required for canonical List index projections.
        /// Other projection kinds must leave this absent until their own
        /// canonical MIR receipt is materialized.
        list_index_contract: Option<types::MirListIndexProjectionContract>,
    },
    /// Consume a non-Copy record product and move one non-Copy field out.
    /// The TypeDesc contract requires every sibling field to be Copy, so the
    /// consumed record has no residual ownership obligation. General
    /// field-level partial move remains a separate MIR shape.
    MoveProject {
        result: MirValueId,
        base: MirValueId,
        projection: MirProjection,
    },
    /// Consume a non-Copy record, move one managed field (owned String or
    /// List<Copy scalar>) out, and drop every residual sibling according to the
    /// attached TypeDesc receipt. This is distinct from `MoveProject`, which
    /// admits only Copy siblings.
    MoveProjectDrop {
        result: MirValueId,
        base: MirValueId,
        projection: MirProjection,
        contract: Option<types::MirRecordMoveProjectionDropContract>,
    },
    /// Read one payload field from the checker-selected active variant.
    /// Unlike a switch binding, this node has no arm-level tag proof, so the
    /// TypeDesc receipt carries the discriminant and explicit active-variant
    /// trap contract. The admitted shape is read-only flat Copy Option/Result;
    /// generic `Option<T>.unwrap()` carries a non-executable placeholder until
    /// concrete instance materialization supplies the Copy-scalar receipt.
    VariantProject {
        result: MirValueId,
        base: MirValueId,
        contract: Option<types::MirVariantProjectionTrapContract>,
    },
    /// Read the selected `Some`/`Ok` payload from a Copy Option/Result, or
    /// return the explicit checker-selected fallback operand for the alternate
    /// tag. The receipt proves both tag identities, payload ABI and Copy
    /// ownership; consumers must not infer this choice from a runtime handle.
    VariantProjectOr {
        result: MirValueId,
        base: MirValueId,
        fallback: MirValueId,
        contract: Option<types::MirVariantProjectionFallbackContract>,
    },
    /// Consume a non-Copy variant and move its single owned payload field
    /// out.  The TypeDesc receipt proves the active discriminant trap and
    /// Move/OwnedString glue; this is intentionally distinct from the
    /// read-only `VariantProject` node so consumers cannot clone by default.
    VariantProjectMove {
        result: MirValueId,
        base: MirValueId,
        contract: Option<types::MirVariantProjectionTrapContract>,
    },
    Construct {
        result: MirValueId,
        kind: MirAggregateKind,
        fields: Vec<MirValueId>,
    },
    /// Construct a move-owned List from element values. The TypeDesc List
    /// contract supplies the element layout and glue; this node carries no
    /// backend-specific capacity or handle representation.
    ConstructList {
        result: MirValueId,
        elements: Vec<MirValueId>,
        /// TypeDesc receipt required for canonical List construction.
        /// Generic placeholders are replaced during concrete instance
        /// materialization before any consumer is invoked.
        list_construct_contract: Option<types::MirListConstructContract>,
    },
    /// Execute a canonical operation over a Copy-scalar List. `Len` returns a
    /// Copy i32 without transferring the source; `Reverse` returns a fresh
    /// move-owned List and leaves the source available for its own Drop;
    /// `Concat` consumes `list` and `argument` and transfers both obligations
    /// into a fresh move-owned result. TypeDesc fixes both List ABI/glue and
    /// result ABI before any consumer is invoked.
    ListOp {
        result: MirValueId,
        operation: MirListOperation,
        list: MirValueId,
        /// The second List input for `Concat`; absent for borrow-only `Len`
        /// and `Reverse`. The receipt repeats its TypeDesc identity.
        argument: Option<MirValueId>,
        /// TypeDesc receipt required for canonical List operations.
        /// Legacy/non-canonical constructors must not be presented as MIR.
        list_operation_contract: Option<types::MirListOperationContract>,
    },
    /// Read the active tag of a flat Copy Option/Result without consuming it.
    /// The receipt is mandatory for canonical consumers.
    VariantPredicate {
        result: MirValueId,
        predicate: MirVariantPredicate,
        variant: MirValueId,
        contract: Option<types::MirVariantPredicateContract>,
    },
    /// Construct a move-owned Set from concrete Copy-scalar elements. The
    /// Set<T> layout, equality representation, and handle glue are supplied
    /// by the TypeDesc catalog.
    ConstructSet {
        result: MirValueId,
        elements: Vec<MirValueId>,
    },
    /// Execute one closed Set operation. `Insert` and `Remove` consume the
    /// receiver and return a new move-owned Set; read operations preserve it.
    SetOp {
        result: MirValueId,
        operation: MirSetOperation,
        set: MirValueId,
        argument: Option<MirValueId>,
    },
    /// Construct a canonical Option/Result variant. Payload identities are
    /// checker-owned; discriminant and physical payload encoding come from
    /// the TypeDesc variant layout.
    ConstructVariant {
        result: MirValueId,
        nominal: NominalTypeId,
        variant: NodeId,
        fields: Vec<(NodeId, MirValueId)>,
    },
    /// Construct a non-Copy Option/Result variant by consuming its payloads.
    /// The TypeDesc variant glue plan proves the payload ownership boundary;
    /// a backend must not lower this as a shallow Copy construction.
    ConstructVariantMove {
        result: MirValueId,
        nominal: NominalTypeId,
        variant: NodeId,
        fields: Vec<(NodeId, MirValueId)>,
    },
    /// Consume a record base and produce the same record with the explicit
    /// field values overlaid.  The field identities in `kind` remain
    /// checker-owned; backend field names are recovered from TypeDesc only.
    UpdateRecord {
        result: MirValueId,
        base: MirValueId,
        kind: MirAggregateKind,
        fields: Vec<MirValueId>,
        /// Generic record updates carry a materialized TypeDesc receipt.  A
        /// concrete non-generic update remains validated by the ordinary
        /// TypeDesc contract and leaves this absent.
        record_update_contract: Option<types::MirRecordUpdateContract>,
        /// Ownership-bearing updates consume the base and carry explicit
        /// old-drop/new-move/residual-move glue. This is mutually exclusive
        /// with `record_update_contract`.
        record_update_move_contract: Option<types::MirRecordUpdateMoveContract>,
    },
    Binary {
        result: MirValueId,
        op: ResolvedBinaryOp,
        left: MirValueId,
        right: MirValueId,
    },
    Unary {
        result: MirValueId,
        op: ResolvedUnaryOp,
        operand: MirValueId,
    },
    Call {
        result: Option<MirValueId>,
        callee: ResolvedCallee,
        /// Checker-finalized generic arguments in binder order.  An empty
        /// list is the canonical marker for a non-generic call.
        type_arguments: Vec<ResolvedTypeId>,
        arguments: Vec<MirValueId>,
        /// Checker-owned effect receipts for ownership-bearing arguments.
        /// Every SessionChan argument must carry a `TransferSession` receipt;
        /// unsupported effect families remain fail-closed.
        effect_receipts: Vec<types::MirCallEffectContract>,
        /// TypeDesc/ABI receipt for a direct call returning a flat Copy
        /// Option/Result. Other call result shapes remain on their existing
        /// explicit compatibility boundary until their own receipt exists.
        variant_call_contract: Option<types::MirVariantCallAbiContract>,
    },
    /// Invoke a checker-resolved Flow transition through its materialized
    /// contract.  This is intentionally distinct from ordinary calls: the
    /// source state is consumed and effect/failure/target facts are carried by
    /// `MirProgram::transitions`, never reconstructed by a backend.
    FlowTransition {
        result: MirValueId,
        transition: NodeId,
        arguments: Vec<MirValueId>,
        /// Explicit checker-owned effect receipt for a non-recoverable
        /// cross-state Boundary transition. Silent and recoverable
        /// transitions have their own contracts and must not carry this
        /// receipt.
        effect_receipt: Option<types::MirFlowEffectReceipt>,
    },
    /// A builtin whose ABI, trap behavior, and ownership boundary have been
    /// fully materialized in the canonical MIR contract. Surface builtin
    /// names must not cross this boundary as backend-local string dispatch.
    BuiltinCall {
        result: MirValueId,
        kind: types::MirBuiltinKind,
        arguments: Vec<MirValueId>,
        /// Optional borrowed String-field receipt for `println`. When
        /// present, the single argument is the owning record rather than the
        /// selected String value; consumers read the field without consuming
        /// the record so a later Flow transition can reuse the state.
        string_field_contract: Option<types::MirStringFieldBorrowContract>,
    },
    /// Consume a checker-resolved SessionChan endpoint through an explicit
    /// residual/effect receipt. Session payloads are present only when the
    /// receipt materializes their TypeDesc/ABI; unsupported shapes fail closed
    /// before any backend sees them.
    SessionCall {
        result: MirValueId,
        operation: types::MirSessionOperation,
        endpoint: MirValueId,
        payload: Option<MirValueId>,
        contract: Option<types::MirSessionCallContract>,
    },
    /// Materialize the two linear endpoints of a checker-typed
    /// `session_pair::<S>()` direct tuple bind. The tuple aggregate itself is
    /// intentionally absent from the MIR value catalog; the receipt proves
    /// both endpoint TypeDesc identities and prevents accidental clone/drop
    /// of a hidden linear aggregate.
    SessionPairBind {
        lo: MirValueId,
        hi: MirValueId,
        contract: Option<types::MirSessionPairBindContract>,
    },
    /// A checked conversion. Source/target facts live in the value catalog
    /// and the eventual lowering contract.
    Convert {
        result: MirValueId,
        source: MirValueId,
    },
    Nop,
}

pub(crate) fn ordinary_map_owner_lifecycle_observer_v1_instruction_id(
    builtin: &str,
    callsite: &NodeId,
) -> MirInstructionId {
    MirInstructionId::new(format!(
        "inst:ordinary_map_owner_lifecycle_observer_v1_{builtin}:{}",
        callsite.0
    ))
    .expect("checked observer callsite yields a canonical MIR instruction identity")
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MirInstruction {
    pub id: MirInstructionId,
    pub kind: MirInstructionKind,
}

/// Canonical contract facts attached to one checker-resolved extern call.
///
/// The declaration expression is lowered to `MirContractExpr` while the
/// checked program is materialized.  Consumers therefore receive the stable
/// extern identity, actual MIR argument identities, and the canonical
/// predicate; they must not reconstruct an FFI call-site from source AST or
/// display names.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MirFfiCallContract {
    pub caller: NodeId,
    /// Stable source-facing callable identity used to keep per-call Requires
    /// and Ensures observations qualified after they leave the MIR graph.
    pub caller_qualified_name: String,
    pub instruction: MirInstructionId,
    /// Exact Resolved Call expression that produced this MIR instruction.
    pub call_node: NodeId,
    pub callee: NodeId,
    /// Checker-owned extern declaration and block identities. Consumers use
    /// these to cross-check the independent source declaration census.
    pub declaration: NodeId,
    pub declaration_block: NodeId,
    /// Checker-resolved C symbol. Consumers must use this identity directly;
    /// they must not recover an extern name from retained surface syntax.
    pub symbol: String,
    /// Checker-resolved ABI spelling. The current production island admits
    /// only the canonical `C` ABI, but keeps the fact in MIR so future ABI
    /// islands cannot silently infer it from a backend declaration.
    pub abi: String,
    pub arguments: Vec<MirValueId>,
    /// Exact source call shape retained alongside the physical MIR argument
    /// vector. This prevents a same-NodeId/value substitution from erasing
    /// checker parameter, conversion, or overload evidence.
    pub selected_signature: String,
    pub source_expression_type: ResolvedTypeId,
    pub source_type_arguments: Vec<ResolvedTypeId>,
    pub source_result_type: ResolvedTypeId,
    pub source_effects: Vec<EffectId>,
    pub source_arguments: Vec<MirFfiSourceArgument>,
    /// Checker-authenticated execution event for this exact call. Its
    /// disposition may remain Deferred for proof consumers, but its scope,
    /// guards, and order cannot be reconstructed from the call NodeId.
    pub source_body_owner: NodeId,
    pub source_statement: NodeId,
    pub source_order: u64,
    pub source_scope: Vec<TypedProofScopeFrame>,
    pub source_guards: Vec<(NodeId, bool)>,
    pub source_match_path: Vec<crate::core::ir::TypedMatchPathReceipt>,
    pub source_disposition: TypedCallExecutionDisposition,
    /// Empty `source_effects` is not evidence of purity. The currently
    /// supported external effect authority always invalidates mutable state.
    pub source_effect_authority: TypedCallEffectAuthority,
    /// Number of fixed declaration parameters before the C ellipsis. This is
    /// distinct from the call-site argument count for variadic declarations.
    pub fixed_argument_count: usize,
    /// Whether the checked declaration uses a C variadic tail. It remains
    /// true when this particular call supplies no tail arguments.
    pub variadic: bool,
    /// Complete fixed declaration identity, including ABI parameter modes.
    pub fixed_parameter_ids: Vec<ResolvedParameterId>,
    pub fixed_parameter_modes: Vec<ResolvedFfiParameterMode>,
    /// One checker-authenticated default-promotion receipt per actual tail
    /// argument, in source evaluation order and indexed in the full argument
    /// vector.
    pub variadic_arguments: Vec<MirFfiVariadicArgument>,
    /// Call-specific physical argument TypeDesc identities. Fixed entries
    /// are the checked declaration types; variadic entries are the promoted
    /// C ABI types. This lets each call carry its own tail while the symbol
    /// shape validator compares only the fixed declaration prefix.
    pub parameter_types: Vec<ResolvedTypeId>,
    /// ABI conversion receipt for each call-site argument. The `from` class is
    /// the MIR value ABI and the `to` class is the declaration ABI; consumers
    /// must apply this receipt instead of maintaining an adapter-local pair
    /// table.
    pub parameter_conversions: Vec<MirFfiAbiConversion>,
    pub result: Option<MirValueId>,
    /// Checker-canonical declaration result TypeDesc identity. A unit-return
    /// declaration carries the canonical unit TypeDesc even when the backend
    /// ABI lowers it as a void result.
    pub result_type: ResolvedTypeId,
    /// Invocation metadata is preserved even where the current backend
    /// profile rejects a field. No consumer may infer errno/no-unwind behavior
    /// from the symbol name or an empty effect list.
    pub block_no_panic: bool,
    pub declaration_no_panic: bool,
    pub block_returns_errno: bool,
    pub declaration_returns_errno: bool,
    pub unsafe_block: bool,
    /// ABI conversion receipt for the returned value, from declaration ABI to
    /// the MIR result ABI. Calls without a MIR result identity carry `None`;
    /// a stable Unit result carries an explicit Unit→Unit conversion.
    pub result_conversion: Option<MirFfiAbiConversion>,
    pub requires: Option<MirContractExpr>,
    pub requires_root: Option<NodeId>,
    pub requires_deferred: bool,
    /// Exact Checker TypeDesc receipt for every node in the Requires tree.
    /// Paths are stable preorder child indices, scoped only to this root.
    pub requires_types: BTreeMap<Vec<u8>, ResolvedTypeId>,
    /// Canonical postcondition attached to the foreign call.  The declaration
    /// `result` leaf is lowered to this call's MIR result value identity so
    /// every consumer observes the same returned scalar rather than a
    /// backend-local result placeholder.
    pub ensures: Option<MirContractExpr>,
    pub ensures_root: Option<NodeId>,
    pub ensures_deferred: bool,
    /// Exact Checker TypeDesc receipt for every node in the Ensures tree.
    /// Paths are stable preorder child indices, scoped only to this root.
    pub ensures_types: BTreeMap<Vec<u8>, ResolvedTypeId>,
    pub span: crate::span::Span,
    /// Private seal minted only after the CheckedProgram call source and the
    /// exact lowered caller body have both been validated. Public NodeIds and
    /// ABI fields alone cannot authorize a substituted same-ID MIR argument.
    source_witness: Option<MirFfiCallSourceWitness>,
}

/// Source-level argument receipt for one exact checked extern invocation.
/// `source_type` and the checked conversion are deliberately separate from a
/// variadic argument's C default-promotion target.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MirFfiSourceArgument {
    pub index: usize,
    pub parameter: ResolvedParameterId,
    pub source_node: NodeId,
    pub source_type: ResolvedTypeId,
    pub conversion: CheckedConversionKind,
    pub conversion_from: ResolvedTypeId,
    pub target_type: ResolvedTypeId,
    /// Checker-authenticated source nodes evaluated eagerly for this exact
    /// argument. The independent proof-source census must reproduce it.
    pub eager_source_nodes: Vec<NodeId>,
}

impl MirFfiSourceArgument {
    fn canonical_text(&self) -> String {
        format!(
            "{}:{}:{}:{}:{:?}:{}:{}:eager={:?}",
            self.index,
            self.parameter.0 .0.as_str(),
            self.source_node.0,
            self.source_type.as_str(),
            self.conversion,
            self.conversion_from.as_str(),
            self.target_type.as_str(),
            self.eager_source_nodes,
        )
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct MirFfiCallSourceWitness {
    checked_source_fingerprint: [u8; 32],
    lowered_mir_fingerprint: [u8; 32],
}

impl MirFfiCallSourceWitness {
    fn validates(&self, contract: &MirFfiCallContract, function: &MirFunction) -> bool {
        self.lowered_mir_fingerprint == Self::lowered_mir_fingerprint(contract, function)
    }

    fn lowered_mir_fingerprint(contract: &MirFfiCallContract, function: &MirFunction) -> [u8; 32] {
        let material = format!(
            "ffi-receipt={}\ncaller-mir={}",
            contract.canonical_text(),
            function.canonical_text()
        );
        *blake3::hash(material.as_bytes()).as_bytes()
    }
}

impl MirFfiCallContract {
    /// Render the semantic FFI receipt body with a backend-independent
    /// spelling.  Diagnostic provenance (`span`) is intentionally omitted:
    /// source remaps must not change the MIR identity digest.
    pub(crate) fn canonical_text(&self) -> String {
        let mut text = String::from("mir.ffi-call-contract.v2\n");
        text.push_str(self.caller.0.as_str());
        text.push_str(" caller_name=");
        text.push_str(&self.caller_qualified_name);
        text.push(' ');
        text.push_str(self.instruction.as_str());
        text.push_str(" call_node=");
        text.push_str(&self.call_node.0);
        text.push(' ');
        text.push_str(self.callee.0.as_str());
        text.push_str(" declaration=");
        text.push_str(&self.declaration.0);
        text.push_str(" declaration_block=");
        text.push_str(&self.declaration_block.0);
        text.push_str(" symbol=");
        text.push_str(&self.symbol);
        text.push_str(" abi=");
        text.push_str(&self.abi);
        text.push_str(" selected_signature=");
        text.push_str(&self.selected_signature);
        text.push_str(" source_expression_type=");
        text.push_str(self.source_expression_type.as_str());
        text.push_str(" source_type_arguments=");
        for ty in &self.source_type_arguments {
            text.push_str(ty.as_str());
            text.push(',');
        }
        text.push_str(" source_result_type=");
        text.push_str(self.source_result_type.as_str());
        text.push_str(" source_effects=");
        for effect in &self.source_effects {
            text.push_str(effect.as_str());
            text.push(',');
        }
        text.push_str(" source_arguments=");
        for argument in &self.source_arguments {
            text.push_str(&argument.canonical_text());
            text.push(';');
        }
        text.push_str(" source_event=");
        text.push_str(&format!(
            "{}:{}:{}:{:?}:{:?}:{:?}:{:?}:{:?}",
            self.source_body_owner.0,
            self.source_statement.0,
            self.source_order,
            self.source_scope,
            self.source_guards,
            self.source_match_path,
            self.source_disposition,
            self.source_effect_authority
        ));
        text.push_str(" fixed_argument_count=");
        text.push_str(&self.fixed_argument_count.to_string());
        text.push_str(" fixed_parameter_ids=");
        for parameter in &self.fixed_parameter_ids {
            text.push_str(parameter.0 .0.as_str());
            text.push(',');
        }
        text.push_str(" fixed_parameter_modes=");
        for mode in &self.fixed_parameter_modes {
            text.push_str(&format!("{mode:?}"));
            text.push(',');
        }
        text.push_str(" variadic=");
        text.push_str(if self.variadic { "true" } else { "false" });
        text.push_str(" args=");
        for argument in &self.arguments {
            text.push_str(argument.as_str());
            text.push(',');
        }
        text.push_str(" parameter_types=");
        for parameter_type in &self.parameter_types {
            text.push_str(parameter_type.as_str());
            text.push(',');
        }
        text.push_str(" parameter_conversions=");
        for conversion in &self.parameter_conversions {
            text.push_str(&conversion.canonical_text());
            text.push(';');
        }
        text.push_str(" variadic_arguments=");
        for argument in &self.variadic_arguments {
            text.push_str(&argument.canonical_text());
            text.push(';');
        }
        text.push_str(" result=");
        text.push_str(
            self.result
                .as_ref()
                .map(MirValueId::as_str)
                .unwrap_or("unit"),
        );
        text.push_str(" result_type=");
        text.push_str(self.result_type.as_str());
        text.push_str(" invocation_flags=");
        text.push_str(&format!(
            "{},{},{},{},{}",
            self.block_no_panic,
            self.declaration_no_panic,
            self.block_returns_errno,
            self.declaration_returns_errno,
            self.unsafe_block
        ));
        text.push_str(" result_conversion=");
        if let Some(conversion) = self.result_conversion {
            text.push_str(&conversion.canonical_text());
        } else {
            text.push_str("none");
        }
        text.push_str(" requires=");
        text.push_str(if self.requires_deferred {
            "deferred:"
        } else {
            "ready:"
        });
        text.push_str(
            self.requires_root
                .as_ref()
                .map(|root| root.0.as_str())
                .unwrap_or("none"),
        );
        text.push(':');
        if let Some(condition) = &self.requires {
            text.push_str(&condition.canonical_text());
        } else {
            text.push_str("none");
        }
        text.push_str(" requires_types=");
        for (path, ty) in &self.requires_types {
            for byte in path {
                let _ = write!(text, "{byte:02x}");
            }
            text.push(':');
            text.push_str(ty.as_str());
            text.push(';');
        }
        text.push_str(" ensures=");
        text.push_str(if self.ensures_deferred {
            "deferred:"
        } else {
            "ready:"
        });
        text.push_str(
            self.ensures_root
                .as_ref()
                .map(|root| root.0.as_str())
                .unwrap_or("none"),
        );
        text.push(':');
        if let Some(condition) = &self.ensures {
            text.push_str(&condition.canonical_text());
        } else {
            text.push_str("none");
        }
        text.push_str(" ensures_types=");
        for (path, ty) in &self.ensures_types {
            for byte in path {
                let _ = write!(text, "{byte:02x}");
            }
            text.push(':');
            text.push_str(ty.as_str());
            text.push(';');
        }
        text.push_str(" source_fingerprint=");
        if let Some(witness) = &self.source_witness {
            for byte in witness.checked_source_fingerprint {
                let _ = write!(text, "{byte:02x}");
            }
        } else {
            text.push_str("missing");
        }
        text
    }

    pub(crate) fn seal_checked_source(
        &mut self,
        function: &MirFunction,
        checked_source_fingerprint: [u8; 32],
    ) {
        self.source_witness = Some(MirFfiCallSourceWitness {
            checked_source_fingerprint,
            lowered_mir_fingerprint: [0; 32],
        });
        let lowered_mir_fingerprint =
            MirFfiCallSourceWitness::lowered_mir_fingerprint(self, function);
        if let Some(witness) = self.source_witness.as_mut() {
            witness.lowered_mir_fingerprint = lowered_mir_fingerprint;
        }
    }

    fn has_valid_source_witness(&self, function: &MirFunction) -> bool {
        self.source_witness
            .as_ref()
            .is_some_and(|witness| witness.validates(self, function))
    }
}

/// C's default-promotion class for one checker-resolved variadic operand.
/// The source/promoted TypeDesc pair is separately sealed in the containing
/// receipt; consumers must validate the pair against this closed rule before
/// creating a physical call interface.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum MirFfiDefaultPromotion {
    Identity,
    IntegerToI32,
    FloatToF64,
}

impl MirFfiDefaultPromotion {
    pub(crate) const fn canonical_text(self) -> &'static str {
        match self {
            Self::Identity => "identity",
            Self::IntegerToI32 => "integer_to_i32",
            Self::FloatToF64 => "float_to_f64",
        }
    }
}

/// Checker-owned provenance and physical type for one actual variadic tail
/// operand. `source_node` must decode from the actual MIR argument identity;
/// the type and promotion fields are rederived from the checked source call.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MirFfiVariadicArgument {
    pub argument_index: usize,
    pub parameter: ResolvedParameterId,
    pub source_node: NodeId,
    pub source_type: ResolvedTypeId,
    pub promoted_type: ResolvedTypeId,
    pub promotion: MirFfiDefaultPromotion,
}

impl MirFfiVariadicArgument {
    fn canonical_text(&self) -> String {
        format!(
            "{}:{}:{}:{}->{}:{}",
            self.argument_index,
            self.parameter.0 .0.as_str(),
            self.source_node.0,
            self.source_type.as_str(),
            self.promoted_type.as_str(),
            self.promotion.canonical_text(),
        )
    }
}

/// One physical scalar ABI conversion at a canonical FFI boundary.
///
/// The checker-owned MIR receipt records the source and target ABI classes so
/// bytecode, native, reference, and verifier consumers all use the same
/// conversion vocabulary. Layout/ownership admission remains part of the
/// resolver below; an arbitrary pair of ABI classes is never accepted.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub struct MirFfiAbiConversion {
    pub from: types::MirAbiClass,
    pub to: types::MirAbiClass,
}

impl MirFfiAbiConversion {
    /// Stable spelling shared by every MIR receipt consumer.
    pub(crate) fn canonical_text(self) -> String {
        format!(
            "{}->{}",
            self.from.canonical_text(),
            self.to.canonical_text()
        )
    }
}

/// Backend-independent classification of one admitted scalar FFI conversion.
/// The direction and widths are part of the MIR receipt contract; adapters
/// only lower this closed classification to LLVM or runtime operations.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub(crate) enum MirFfiConversionKind {
    Identity { abi: types::MirAbiClass },
    SignedIntegerWiden { from_bits: u16, to_bits: u16 },
    SignedIntegerToFloat { from_bits: u16 },
    IntegerPromotionToI32 { from: types::MirAbiClass },
    FloatWiden { from_bits: u16, to_bits: u16 },
    SignedIntegerNarrow { from_bits: u16, to_bits: u16 },
    FloatToSignedInteger { to_bits: u16 },
}

impl MirFfiAbiConversion {
    fn canonical_identity(abi: types::MirAbiClass) -> bool {
        abi.canonical_ffi_scalar_kind().is_some()
    }

    fn conversion_kind_for(
        from: types::MirAbiClass,
        to: types::MirAbiClass,
    ) -> Option<MirFfiConversionKind> {
        if from == to {
            return Self::canonical_identity(from)
                .then_some(MirFfiConversionKind::Identity { abi: from });
        }
        match (from, to) {
            (
                types::MirAbiClass::Integer {
                    bits: 32,
                    signed: true,
                },
                types::MirAbiClass::Integer {
                    bits: 64,
                    signed: true,
                },
            ) => Some(MirFfiConversionKind::SignedIntegerWiden {
                from_bits: 32,
                to_bits: 64,
            }),
            (
                types::MirAbiClass::Integer {
                    bits: from_bits @ (32 | 64),
                    signed: true,
                },
                types::MirAbiClass::Float { bits: 64 },
            ) => Some(MirFfiConversionKind::SignedIntegerToFloat { from_bits }),
            (
                from @ types::MirAbiClass::Integer {
                    bits: 8 | 16,
                    signed: _,
                },
                types::MirAbiClass::Integer {
                    bits: 32,
                    signed: true,
                },
            )
            | (
                from @ types::MirAbiClass::Bool,
                types::MirAbiClass::Integer {
                    bits: 32,
                    signed: true,
                },
            ) => Some(MirFfiConversionKind::IntegerPromotionToI32 { from }),
            (types::MirAbiClass::Float { bits: 32 }, types::MirAbiClass::Float { bits: 64 }) => {
                Some(MirFfiConversionKind::FloatWiden {
                    from_bits: 32,
                    to_bits: 64,
                })
            }
            (
                types::MirAbiClass::Integer {
                    bits: 64,
                    signed: true,
                },
                types::MirAbiClass::Integer {
                    bits: 32,
                    signed: true,
                },
            ) => Some(MirFfiConversionKind::SignedIntegerNarrow {
                from_bits: 64,
                to_bits: 32,
            }),
            (
                types::MirAbiClass::Float { bits: 64 },
                types::MirAbiClass::Integer {
                    bits: to_bits @ (32 | 64),
                    signed: true,
                },
            ) => Some(MirFfiConversionKind::FloatToSignedInteger { to_bits }),
            _ => None,
        }
    }

    pub(crate) fn kind(self) -> Option<MirFfiConversionKind> {
        Self::conversion_kind_for(self.from, self.to)
    }

    fn argument_kind(self) -> Option<MirFfiConversionKind> {
        let kind = self.kind()?;
        match kind {
            MirFfiConversionKind::Identity { abi } if abi == types::MirAbiClass::Unit => None,
            MirFfiConversionKind::Identity { .. }
            | MirFfiConversionKind::SignedIntegerWiden { .. }
            | MirFfiConversionKind::SignedIntegerToFloat { .. }
            | MirFfiConversionKind::IntegerPromotionToI32 { .. }
            | MirFfiConversionKind::FloatWiden { .. } => Some(kind),
            _ => None,
        }
    }

    fn result_kind(self) -> Option<MirFfiConversionKind> {
        let kind = self.kind()?;
        matches!(
            kind,
            MirFfiConversionKind::Identity { .. }
                | MirFfiConversionKind::SignedIntegerNarrow { .. }
                | MirFfiConversionKind::FloatToSignedInteger { .. }
        )
        .then_some(kind)
    }

    /// Whether this receipt describes one of the physical argument conversions
    /// admitted by the scalar C FFI island. Keeping this independent from a
    /// TypeDesc catalog lets the AST-free bytecode descriptor preflight reject
    /// a hand-built conversion before it loads or calls a foreign symbol.
    pub(crate) fn is_supported_argument(self) -> bool {
        self.argument_kind().is_some()
    }

    /// Whether this receipt describes one of the physical result conversions
    /// admitted by the scalar C FFI island. Result conversion is the inverse
    /// direction of argument widening, so its non-identity set is deliberately
    /// different from [`Self::is_supported_argument`].
    pub(crate) fn is_supported_result(self) -> bool {
        self.result_kind().is_some()
    }

    /// Return the half-open mathematical range accepted by the canonical
    /// f64-to-signed-integer result conversion.  Keeping the bounds in the
    /// MIR contract prevents reference, bytecode, and native consumers from
    /// drifting at the exact representational edges (especially i64::MAX,
    /// which is not exactly representable as f64).
    pub(crate) fn float_to_signed_integer_bounds(to_bits: u16) -> Option<(f64, f64)> {
        match to_bits {
            32 => Some((i32::MIN as f64, (i32::MAX as f64) + 1.0)),
            64 => Some((i64::MIN as f64, 9_223_372_036_854_775_808.0)),
            _ => None,
        }
    }

    /// Return the closed mathematical range accepted by the canonical
    /// signed-integer narrowing result conversion.  The MIR contract owns
    /// these bounds so native's generated guard cannot drift from the
    /// reference and bytecode `i32::try_from` paths at either edge.
    pub(crate) fn signed_integer_narrow_bounds(to_bits: u16) -> Option<(i64, i64)> {
        match to_bits {
            32 => Some((i32::MIN as i64, i32::MAX as i64)),
            64 => Some((i64::MIN, i64::MAX)),
            _ => None,
        }
    }

    fn scalar_copy(desc: &types::MirTypeDesc) -> bool {
        desc.is_canonical_ffi_scalar()
    }

    /// Resolve the checker-approved argument conversion (MIR value to C
    /// declaration). This is the only admitted parameter direction.
    pub(crate) fn for_argument(
        catalog: &types::MirTypeCatalog,
        actual: &ResolvedTypeId,
        declared: &ResolvedTypeId,
    ) -> Option<Self> {
        let actual_desc = catalog.get(actual)?;
        let declared_desc = catalog.get(declared)?;
        if actual == declared {
            return Some(Self {
                from: actual_desc.abi,
                to: declared_desc.abi,
            });
        }
        if !Self::scalar_copy(actual_desc) || !Self::scalar_copy(declared_desc) {
            return None;
        }
        let conversion = Self {
            from: actual_desc.abi,
            to: declared_desc.abi,
        };
        conversion.argument_kind().map(|_| conversion)
    }

    /// Resolve one variadic operand's physical conversion from its exact
    /// checked source type and default-promotion receipt. Unlike the fixed
    /// parameter helper, this deliberately admits narrow integer/bool/f32
    /// *sources* whose physical call arguments are the promoted C types.
    pub(crate) fn for_variadic_argument(
        catalog: &types::MirTypeCatalog,
        source: &ResolvedTypeId,
        promoted: &ResolvedTypeId,
        promotion: MirFfiDefaultPromotion,
    ) -> Option<Self> {
        let source_desc = catalog.get(source)?;
        let promoted_desc = catalog.get(promoted)?;
        if !promoted_desc.is_canonical_ffi_scalar() {
            return None;
        }
        let valid = match promotion {
            MirFfiDefaultPromotion::Identity => {
                source == promoted
                    && source_desc.is_canonical_ffi_scalar()
                    && !matches!(
                        &source_desc.kind,
                        types::MirTypeKind::Primitive(
                            crate::core::ir::PrimitiveType::Bool
                                | crate::core::ir::PrimitiveType::F32
                        )
                    )
            }
            MirFfiDefaultPromotion::IntegerToI32 => {
                matches!(
                    &promoted_desc.kind,
                    types::MirTypeKind::Primitive(crate::core::ir::PrimitiveType::I32)
                ) && matches!(
                    (&source_desc.kind, source_desc.abi),
                    (
                        types::MirTypeKind::Primitive(crate::core::ir::PrimitiveType::Bool),
                        types::MirAbiClass::Bool
                    ) | (
                        types::MirTypeKind::Primitive(crate::core::ir::PrimitiveType::I8),
                        types::MirAbiClass::Integer {
                            bits: 8,
                            signed: true
                        }
                    ) | (
                        types::MirTypeKind::Primitive(crate::core::ir::PrimitiveType::I16),
                        types::MirAbiClass::Integer {
                            bits: 16,
                            signed: true
                        }
                    ) | (
                        types::MirTypeKind::Primitive(crate::core::ir::PrimitiveType::U8),
                        types::MirAbiClass::Integer {
                            bits: 8,
                            signed: false
                        }
                    ) | (
                        types::MirTypeKind::Primitive(crate::core::ir::PrimitiveType::U16),
                        types::MirAbiClass::Integer {
                            bits: 16,
                            signed: false
                        }
                    )
                ) && source_desc.layout == types::MirLayout::Scalar
                    && source_desc.has_canonical_copy_noop_metadata()
            }
            MirFfiDefaultPromotion::FloatToF64 => {
                matches!(
                    &source_desc.kind,
                    types::MirTypeKind::Primitive(crate::core::ir::PrimitiveType::F32)
                ) && matches!(
                    &promoted_desc.kind,
                    types::MirTypeKind::Primitive(crate::core::ir::PrimitiveType::F64)
                ) && source_desc.is_canonical_copy_scalar(true)
            }
        };
        valid.then_some(Self {
            from: source_desc.abi,
            to: promoted_desc.abi,
        })
    }

    /// Resolve the checker-approved result conversion (C declaration to MIR
    /// result). It is the inverse physical direction of the admitted
    /// argument widening where needed by the result slot.
    pub(crate) fn for_result(
        catalog: &types::MirTypeCatalog,
        actual: &ResolvedTypeId,
        declared: &ResolvedTypeId,
    ) -> Option<Self> {
        let actual_desc = catalog.get(actual)?;
        let declared_desc = catalog.get(declared)?;
        if actual == declared {
            return Some(Self {
                from: declared_desc.abi,
                to: actual_desc.abi,
            });
        }
        if !Self::scalar_copy(actual_desc) || !Self::scalar_copy(declared_desc) {
            return None;
        }
        let conversion = Self {
            from: declared_desc.abi,
            to: actual_desc.abi,
        };
        conversion.result_kind().map(|_| conversion)
    }
}

/// Validate the checker-owned identity and ABI receipt for one direct extern
/// call.  This is deliberately independent of any backend representation so
/// native, verifier, and capability consumers cannot accept a forged
/// conversion, declaration shape, or extern symbol identity that the
/// reference/bytecode adapters would reject.
pub(crate) fn validate_ffi_call_contract_receipt(
    type_catalog: &types::MirTypeCatalog,
    function: &MirFunction,
    instruction: &MirInstructionId,
    callee: &NodeId,
    result: Option<&MirValueId>,
    arguments: &[MirValueId],
    contract: &MirFfiCallContract,
) -> Vec<String> {
    validate_ffi_call_contract_receipt_with_policy(
        type_catalog,
        function,
        instruction,
        callee,
        result,
        arguments,
        contract,
        FfiCallContractReceiptPolicy::ScalarExecution,
    )
}

/// Validate a receipt while constructing canonical MIR, before a consumer has
/// selected an execution island.  The constructor shares all receipt identity,
/// declaration, conversion-shape, symbol, and contract checks, but leaves the
/// narrow scalar-island conversion whitelist to each backend's admission gate.
/// This preserves the canonical MIR ability to carry a future non-scalar FFI
/// declaration while keeping today's scalar consumers fail-closed.
pub(crate) fn validate_ffi_call_contract_receipt_at_mir_boundary(
    type_catalog: &types::MirTypeCatalog,
    function: &MirFunction,
    instruction: &MirInstructionId,
    callee: &NodeId,
    result: Option<&MirValueId>,
    arguments: &[MirValueId],
    contract: &MirFfiCallContract,
) -> Vec<String> {
    validate_ffi_call_contract_receipt_with_policy(
        type_catalog,
        function,
        instruction,
        callee,
        result,
        arguments,
        contract,
        FfiCallContractReceiptPolicy::CanonicalMir,
    )
}

/// Validate the same checker-sealed identity, source/ABI conversion chain and
/// typed contract tree as canonical MIR, while admitting the narrow owned
/// StringHandle endpoints understood by the MIR proof engine. This is a
/// verifier-only policy: execution consumers continue to call the scalar
/// validator above, and this policy does not widen ScalarFfi route admission.
pub(crate) fn validate_ffi_call_contract_verifier_receipt(
    type_catalog: &types::MirTypeCatalog,
    function: &MirFunction,
    instruction: &MirInstructionId,
    callee: &NodeId,
    result: Option<&MirValueId>,
    arguments: &[MirValueId],
    contract: &MirFfiCallContract,
) -> Vec<String> {
    validate_ffi_call_contract_receipt_with_policy(
        type_catalog,
        function,
        instruction,
        callee,
        result,
        arguments,
        contract,
        FfiCallContractReceiptPolicy::TypedStringVerifier,
    )
}

/// Validate the checker-sealed FFI receipt for the verifier-only scalar-leaf
/// `repr(C)` record proof profile. This policy is consumed only by verifier
/// proof callers; ScalarFfi execution continues through the scalar validator.
pub(crate) fn validate_ffi_call_contract_verifier_record_receipt(
    type_catalog: &types::MirTypeCatalog,
    function: &MirFunction,
    instruction: &MirInstructionId,
    callee: &NodeId,
    result: Option<&MirValueId>,
    arguments: &[MirValueId],
    contract: &MirFfiCallContract,
) -> Vec<String> {
    validate_ffi_call_contract_receipt_with_policy(
        type_catalog,
        function,
        instruction,
        callee,
        result,
        arguments,
        contract,
        FfiCallContractReceiptPolicy::ReprCRecordVerifier,
    )
}

/// Select the narrow verifier-only policy for scalar FFI preconditions whose
/// checked declaration carries invocation metadata outside the execution
/// island. The policy itself validates the exact allowed subset; this
/// predicate only ensures such calls cannot fall through to the ordinary
/// scalar execution receipt validator.
pub(crate) fn ffi_call_uses_scalar_requires_verifier_policy(contract: &MirFfiCallContract) -> bool {
    contract.block_no_panic
        || contract.declaration_no_panic
        || contract.block_returns_errno
        || contract.declaration_returns_errno
        || contract.unsafe_block
        || contract.variadic
        || contract
            .fixed_parameter_modes
            .iter()
            .any(|mode| *mode != ResolvedFfiParameterMode::Value)
}

/// Validate the checker-sealed scalar FFI receipt for a verifier-only
/// Requires proof. This policy admits `errno`, `no_panic`, and Borrow metadata
/// because they do not alter the truth of the pre-call predicate. It does not
/// model their invocation effects, Move/Cap ownership, foreign Ensures, or a
/// variadic tail, and is never used by execution consumers.
pub(crate) fn validate_ffi_call_contract_verifier_scalar_requires_receipt(
    type_catalog: &types::MirTypeCatalog,
    function: &MirFunction,
    instruction: &MirInstructionId,
    callee: &NodeId,
    result: Option<&MirValueId>,
    arguments: &[MirValueId],
    contract: &MirFfiCallContract,
) -> Vec<String> {
    validate_ffi_call_contract_receipt_with_policy(
        type_catalog,
        function,
        instruction,
        callee,
        result,
        arguments,
        contract,
        FfiCallContractReceiptPolicy::ScalarRequiresVerifier,
    )
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum FfiCallContractReceiptPolicy {
    ScalarExecution,
    CanonicalMir,
    TypedStringVerifier,
    ReprCRecordVerifier,
    ScalarRequiresVerifier,
}

fn validate_ffi_call_contract_receipt_with_policy(
    type_catalog: &types::MirTypeCatalog,
    function: &MirFunction,
    instruction: &MirInstructionId,
    callee: &NodeId,
    result: Option<&MirValueId>,
    arguments: &[MirValueId],
    contract: &MirFfiCallContract,
    policy: FfiCallContractReceiptPolicy,
) -> Vec<String> {
    let mut errors = Vec::new();
    let enforce_scalar_abi = matches!(
        policy,
        FfiCallContractReceiptPolicy::ScalarExecution
            | FfiCallContractReceiptPolicy::ScalarRequiresVerifier
    );
    if contract.caller != function.owner
        || contract.instruction != *instruction
        || contract.callee != *callee
    {
        errors.push("extern call FFI contract identity disagrees with MIR call".into());
    }
    if contract.result.as_ref() != result {
        errors.push("extern call FFI contract result disagrees with MIR call".into());
        if let Some(result_value) = contract.result.as_ref() {
            if !function.values.contains_key(result_value) {
                errors.push(format!(
                    "extern call FFI contract result value identity is absent (MIR value '{}' is absent)",
                    result_value,
                ));
            }
        }
    }
    if contract.abi != "C" {
        errors.push(format!(
            "{}: extern call FFI contract ABI '{}' is outside the canonical C ABI",
            crate::diagnostic::codes::MIR_FFI_DECLARATION_BOUNDARY_ERROR_CODE,
            contract.abi,
        ));
    }
    if let Err(message) = validate_ffi_symbol_manifest_safety(&contract.symbol) {
        errors.push(format!("extern call {message}"));
    } else if let Err(message) = validate_ffi_symbol_matches_callee(callee, &contract.symbol) {
        errors.push(message);
    }
    if contract.arguments != arguments {
        errors.push("extern call FFI contract arguments disagree with MIR call".into());
        for (index, argument) in contract.arguments.iter().enumerate() {
            if !function.values.contains_key(argument) {
                errors.push(format!(
                    "extern call FFI contract argument {index} value identity is absent (MIR value '{}' is absent)",
                    argument,
                ));
            }
        }
    }
    if result.is_some_and(|result| arguments.iter().any(|argument| argument == result)) {
        errors.push("extern call FFI result identity overlaps an argument identity".into());
    }
    if contract.fixed_argument_count > arguments.len() {
        errors.push("extern call FFI fixed argument count exceeds the MIR argument count".into());
    }
    if contract.parameter_types.len() != arguments.len() {
        errors.push(
            "extern call FFI physical parameter TypeDesc count disagrees with MIR arguments".into(),
        );
    }
    if contract.parameter_conversions.len() != arguments.len() {
        errors.push(
            "extern call FFI parameter ABI conversion receipt count disagrees with MIR arguments"
                .into(),
        );
    }
    if policy == FfiCallContractReceiptPolicy::ScalarRequiresVerifier {
        if contract.requires.is_none()
            || contract.requires_deferred
            || contract.requires_root.is_none()
            || contract.requires_types.is_empty()
        {
            errors.push(
                "verifier scalar invocation-metadata policy requires one Ready typed Requires root"
                    .into(),
            );
        }
        if contract.ensures.is_some()
            || contract.ensures_deferred
            || contract.ensures_root.is_some()
            || !contract.ensures_types.is_empty()
        {
            errors.push(
                "verifier scalar invocation-metadata policy does not admit foreign Ensures".into(),
            );
        }
        if contract.unsafe_block {
            errors.push(
                "verifier scalar invocation-metadata policy does not admit unsafe extern blocks"
                    .into(),
            );
        }
        if contract
            .fixed_parameter_modes
            .contains(&ResolvedFfiParameterMode::Move)
        {
            errors.push(
                "verifier scalar invocation-metadata policy does not admit Move/Cap parameter modes"
                    .into(),
            );
        }
        if contract.variadic
            && (contract.fixed_argument_count != arguments.len()
                || !contract.variadic_arguments.is_empty())
        {
            errors.push(
                "verifier scalar invocation-metadata policy admits variadic declarations only with an empty checked tail"
                    .into(),
            );
        }
    }
    if policy == FfiCallContractReceiptPolicy::ScalarExecution {
        if contract.requires_deferred {
            errors.push(SCALAR_FFI_DEFERRED_REQUIRES_ERROR.into());
        }
        if contract.ensures_deferred {
            errors.push(SCALAR_FFI_DEFERRED_ENSURES_ERROR.into());
        }
    }
    if policy != FfiCallContractReceiptPolicy::CanonicalMir
        && policy != FfiCallContractReceiptPolicy::ScalarRequiresVerifier
        && (contract.block_no_panic
            || contract.declaration_no_panic
            || contract.block_returns_errno
            || contract.declaration_returns_errno
            || contract
                .fixed_parameter_modes
                .iter()
                .any(|mode| *mode != ResolvedFfiParameterMode::Value))
    {
        errors.push(format!(
            "{}: extern call uses no-unwind, errno, or non-Value mode semantics without an execution receipt",
            crate::diagnostic::codes::MIR_FFI_DECLARATION_BOUNDARY_ERROR_CODE
        ));
    }
    let fixed_count_is_valid = contract.fixed_argument_count <= arguments.len();
    let expected_tail_count = arguments
        .len()
        .saturating_sub(contract.fixed_argument_count);
    if contract.variadic {
        if contract.fixed_argument_count == 0 {
            errors
                .push("extern call FFI variadic declaration has no fixed parameter prefix".into());
        }
        if contract.variadic_arguments.len() != expected_tail_count {
            errors.push(
                "extern call FFI variadic promotion receipt count disagrees with actual tail arguments"
                    .into(),
            );
        }
    } else if contract.fixed_argument_count != arguments.len()
        || !contract.variadic_arguments.is_empty()
    {
        errors.push("extern call FFI non-variadic receipt contains variadic tail metadata".into());
    }
    if enforce_scalar_abi {
        for (index, declared_type) in contract
            .parameter_types
            .iter()
            .take(
                contract
                    .fixed_argument_count
                    .min(contract.parameter_types.len()),
            )
            .enumerate()
        {
            if !type_catalog.is_canonical_ffi_endpoint(declared_type, false) {
                errors.push(format!(
                    "{}: extern call FFI declaration parameter {index} TypeDesc is outside the complete scalar endpoint contract",
                    crate::diagnostic::codes::MIR_FFI_DECLARATION_BOUNDARY_ERROR_CODE
                ));
            }
        }
        for tail in &contract.variadic_arguments {
            if !type_catalog.is_canonical_ffi_endpoint(&tail.promoted_type, false) {
                errors.push(format!(
                    "{}: extern call FFI variadic argument {} promoted TypeDesc is outside the complete scalar endpoint contract",
                    crate::diagnostic::codes::MIR_FFI_DECLARATION_BOUNDARY_ERROR_CODE,
                    tail.argument_index
                ));
            }
        }
        let canonical_result = if result.is_some() {
            type_catalog.is_canonical_ffi_endpoint(&contract.result_type, true)
        } else {
            type_catalog
                .get(&contract.result_type)
                .is_some_and(types::MirTypeDesc::is_canonical_ffi_unit)
        };
        if !canonical_result {
            errors.push(
                format!(
                    "{}: extern call FFI declaration result TypeDesc is outside the complete scalar endpoint contract",
                    crate::diagnostic::codes::MIR_FFI_DECLARATION_BOUNDARY_ERROR_CODE
                ),
            );
        }
    }
    if policy == FfiCallContractReceiptPolicy::TypedStringVerifier {
        let is_verifier_endpoint = |ty: &ResolvedTypeId, result_endpoint: bool| {
            type_catalog.is_canonical_ffi_endpoint(ty, result_endpoint)
                || type_catalog.validate_owned_string(ty).is_ok()
        };
        let has_string_endpoint = contract
            .parameter_types
            .iter()
            .take(
                contract
                    .fixed_argument_count
                    .min(contract.parameter_types.len()),
            )
            .any(|ty| type_catalog.validate_owned_string(ty).is_ok())
            || (result.is_some()
                && type_catalog
                    .validate_owned_string(&contract.result_type)
                    .is_ok());
        if !has_string_endpoint {
            errors.push(
                "verifier StringHandle FFI receipt policy requires a canonical StringHandle endpoint"
                    .into(),
            );
        }
        for (index, ty) in contract
            .parameter_types
            .iter()
            .take(
                contract
                    .fixed_argument_count
                    .min(contract.parameter_types.len()),
            )
            .enumerate()
        {
            if !is_verifier_endpoint(ty, false) {
                errors.push(format!(
                    "{}: verifier StringHandle FFI parameter {index} TypeDesc is outside the canonical scalar-or-StringHandle endpoint contract",
                    crate::diagnostic::codes::MIR_FFI_DECLARATION_BOUNDARY_ERROR_CODE
                ));
            }
        }
        for tail in &contract.variadic_arguments {
            if !type_catalog.is_canonical_ffi_endpoint(&tail.promoted_type, false) {
                errors.push(format!(
                    "{}: verifier StringHandle FFI variadic argument {} is outside the canonical scalar endpoint contract",
                    crate::diagnostic::codes::MIR_FFI_DECLARATION_BOUNDARY_ERROR_CODE,
                    tail.argument_index
                ));
            }
        }
        let result_type_is_supported = if result.is_some() {
            is_verifier_endpoint(&contract.result_type, true)
        } else {
            type_catalog
                .get(&contract.result_type)
                .is_some_and(types::MirTypeDesc::is_canonical_ffi_unit)
        };
        if !result_type_is_supported {
            errors.push(format!(
                "{}: verifier StringHandle FFI result TypeDesc is outside the canonical scalar-or-StringHandle endpoint contract",
                crate::diagnostic::codes::MIR_FFI_DECLARATION_BOUNDARY_ERROR_CODE
            ));
        }
    }
    if policy == FfiCallContractReceiptPolicy::ReprCRecordVerifier {
        let is_scalar_leaf = |ty: &ResolvedTypeId| {
            type_catalog
                .get(ty)
                .is_some_and(types::MirTypeDesc::is_canonical_ffi_verifier_scalar_leaf)
        };
        let is_record = |ty: &ResolvedTypeId| {
            type_catalog.is_canonical_ffi_verifier_record(ty)
                || type_catalog.is_canonical_ffi_verifier_string_record(ty)
        };
        let is_endpoint = |ty: &ResolvedTypeId| is_scalar_leaf(ty) || is_record(ty);
        let has_record_endpoint = contract
            .parameter_types
            .iter()
            .take(
                contract
                    .fixed_argument_count
                    .min(contract.parameter_types.len()),
            )
            .any(is_record)
            || (result.is_some() && is_record(&contract.result_type));
        if !has_record_endpoint {
            errors.push(
                "verifier repr(C) record FFI receipt policy requires a validated record endpoint"
                    .into(),
            );
        }
        if contract.variadic {
            errors.push(
                "verifier repr(C) record FFI receipt policy does not admit variadic declarations"
                    .into(),
            );
        }
        for (index, ty) in contract
            .parameter_types
            .iter()
            .take(
                contract
                    .fixed_argument_count
                    .min(contract.parameter_types.len()),
            )
            .enumerate()
        {
            if !is_endpoint(ty) {
                errors.push(format!(
                    "{}: verifier repr(C) record FFI parameter {index} is outside the i32/i64/bool/f64 or checked scalar/String repr(C) record endpoint contract",
                    crate::diagnostic::codes::MIR_FFI_DECLARATION_BOUNDARY_ERROR_CODE
                ));
            }
        }
        for tail in &contract.variadic_arguments {
            if !is_scalar_leaf(&tail.promoted_type) {
                errors.push(format!(
                    "{}: verifier repr(C) record FFI variadic argument {} is outside the scalar leaf domain",
                    crate::diagnostic::codes::MIR_FFI_DECLARATION_BOUNDARY_ERROR_CODE,
                    tail.argument_index
                ));
            }
        }
        let result_type_is_supported = if result.is_some() {
            is_endpoint(&contract.result_type)
        } else {
            type_catalog
                .get(&contract.result_type)
                .is_some_and(types::MirTypeDesc::is_canonical_ffi_unit)
        };
        if !result_type_is_supported {
            errors.push(format!(
                "{}: verifier repr(C) record FFI result is outside the i32/i64/bool/f64 or checked scalar/String repr(C) record endpoint contract",
                crate::diagnostic::codes::MIR_FFI_DECLARATION_BOUNDARY_ERROR_CODE
            ));
        }
    }
    for (index, (argument, declared_type)) in arguments
        .iter()
        .take(
            contract
                .fixed_argument_count
                .min(contract.parameter_types.len()),
        )
        .zip(&contract.parameter_types)
        .enumerate()
    {
        let Some(argument_value) = function.values.get(argument) else {
            errors.push(format!(
                "extern call FFI contract argument {index} value identity is absent (MIR value '{}' is absent)",
                argument,
            ));
            continue;
        };
        if !reference::ffi_type_compatible(type_catalog, &argument_value.ty, declared_type) {
            errors.push(format!(
                "extern call FFI declaration parameter {index} TypeDesc disagrees with MIR argument"
            ));
        }
        if policy == FfiCallContractReceiptPolicy::ReprCRecordVerifier
            && !(type_catalog
                .get(&argument_value.ty)
                .is_some_and(types::MirTypeDesc::is_canonical_ffi_verifier_scalar_leaf)
                || type_catalog.is_canonical_ffi_verifier_record(&argument_value.ty)
                || type_catalog.is_canonical_ffi_verifier_string_record(&argument_value.ty))
        {
            errors.push(format!(
                "extern call FFI argument {index} source TypeDesc is outside the verifier repr(C) record endpoint contract"
            ));
        }
        if let Some(receipt_conversion) = contract.parameter_conversions.get(index) {
            if enforce_scalar_abi && !receipt_conversion.is_supported_argument() {
                errors.push(format!(
                    "extern call FFI parameter {index} ABI conversion from {:?} to {:?} is unsupported",
                    receipt_conversion.from, receipt_conversion.to
                ));
            }
            let expected =
                MirFfiAbiConversion::for_argument(type_catalog, &argument_value.ty, declared_type);
            if expected.as_ref() != Some(receipt_conversion) {
                errors.push(format!(
                    "extern call FFI parameter {index} ABI conversion receipt disagrees with MIR value"
                ));
            }
        }
    }
    if fixed_count_is_valid && contract.variadic {
        for (tail_offset, tail) in contract.variadic_arguments.iter().enumerate() {
            let index = contract.fixed_argument_count + tail_offset;
            if tail.argument_index != index {
                errors.push(format!(
                    "extern call FFI variadic receipt ordinal {} appears at index {}, expected {index}",
                    tail.argument_index, tail_offset
                ));
            }
            let Some(argument) = arguments.get(index) else {
                errors.push(format!(
                    "extern call FFI variadic receipt {index} is outside the MIR argument list"
                ));
                continue;
            };
            let actual_source_node = argument
                .as_str()
                .strip_prefix("expr:")
                .map(|node| NodeId(node.to_owned()));
            if actual_source_node.as_ref() != Some(&tail.source_node) {
                errors.push(format!(
                    "extern call FFI variadic argument {index} source node disagrees with its MIR argument identity"
                ));
            }
            let Some(argument_value) = function.values.get(argument) else {
                errors.push(format!(
                    "extern call FFI variadic argument {index} value identity is absent (MIR value '{}' is absent)",
                    argument
                ));
                continue;
            };
            if argument_value.ty != tail.source_type {
                errors.push(format!(
                    "extern call FFI variadic argument {index} source TypeDesc disagrees with MIR value"
                ));
            }
            if contract.parameter_types.get(index) != Some(&tail.promoted_type) {
                errors.push(format!(
                    "extern call FFI variadic argument {index} promoted TypeDesc disagrees with physical parameter type"
                ));
            }
            let Some(receipt_conversion) = contract.parameter_conversions.get(index) else {
                errors.push(format!(
                    "extern call FFI variadic argument {index} has no ABI conversion receipt"
                ));
                continue;
            };
            let expected_conversion = MirFfiAbiConversion::for_variadic_argument(
                type_catalog,
                &tail.source_type,
                &tail.promoted_type,
                tail.promotion,
            );
            if expected_conversion.as_ref() != Some(receipt_conversion) {
                errors.push(format!(
                    "extern call FFI variadic argument {index} promotion conversion receipt disagrees with the checked source/promotion TypeDescs"
                ));
            }
            if enforce_scalar_abi && !receipt_conversion.is_supported_argument() {
                errors.push(format!(
                    "extern call FFI variadic argument {index} ABI conversion from {:?} to {:?} is unsupported",
                    receipt_conversion.from, receipt_conversion.to
                ));
            }
        }
    }
    if let Some(result_value) = result {
        let Some(value) = function.values.get(result_value) else {
            errors.push(format!(
                "extern call FFI contract result value identity is absent (MIR value '{}' is absent)",
                result_value,
            ));
            return errors;
        };
        if !reference::ffi_type_compatible(type_catalog, &value.ty, &contract.result_type) {
            errors.push(
                "extern call FFI declaration result TypeDesc disagrees with MIR result".into(),
            );
        }
        if policy == FfiCallContractReceiptPolicy::ReprCRecordVerifier
            && !(type_catalog
                .get(&value.ty)
                .is_some_and(types::MirTypeDesc::is_canonical_ffi_verifier_scalar_leaf)
                || type_catalog.is_canonical_ffi_verifier_record(&value.ty)
                || type_catalog.is_canonical_ffi_verifier_string_record(&value.ty))
        {
            errors.push(
                "extern call FFI result source TypeDesc is outside the verifier repr(C) record endpoint contract"
                    .into(),
            );
        }
        let expected =
            MirFfiAbiConversion::for_result(type_catalog, &value.ty, &contract.result_type);
        if let Some(receipt_conversion) = contract.result_conversion.as_ref() {
            if enforce_scalar_abi && !receipt_conversion.is_supported_result() {
                errors.push(format!(
                    "extern call FFI result ABI conversion from {:?} to {:?} is unsupported",
                    receipt_conversion.from, receipt_conversion.to
                ));
            }
        }
        if contract.result_conversion.as_ref() != expected.as_ref() {
            errors.push(
                "extern call FFI result ABI conversion receipt disagrees with MIR result".into(),
            );
        }
    } else if contract.result_conversion.is_some() {
        errors.push(
            "extern call FFI result ABI conversion receipt is present for a unit call".into(),
        );
    }
    if enforce_scalar_abi {
        if let Err(message) = contracts::validate_ffi_requires(function, type_catalog, contract) {
            errors.push(message);
        }
        if let Err(message) = contracts::validate_ffi_ensures(function, type_catalog, contract) {
            errors.push(message);
        }
    }
    if let Err(message) = contracts::validate_ffi_mir_contracts(function, type_catalog, contract) {
        errors.push(message);
    }
    if policy == FfiCallContractReceiptPolicy::ReprCRecordVerifier {
        if let Err(message) =
            contracts::validate_ffi_record_verifier_contracts(type_catalog, contract)
        {
            errors.push(message);
        }
    }
    if !contract.has_valid_source_witness(function) {
        errors.push(
            "extern call FFI checked-source witness disagrees with the conversion receipt, checked source, or lowered caller MIR"
                .into(),
        );
    }
    errors
}

/// Validate that every checker-owned FFI receipt is attached to an actual
/// extern MIR call. The canonical `MirProgram` constructor already enforces
/// this relation, but consumers also need the check because tests and
/// diagnostics may deliberately bypass construction to probe fail-closed
/// behavior. An orphaned receipt must never be silently ignored by a backend
/// that scans calls rather than the receipt table.
pub(crate) fn validate_ffi_receipt_table(
    functions: &BTreeMap<NodeId, MirFunction>,
    ffi_calls: &BTreeMap<MirInstructionId, MirFfiCallContract>,
) -> Vec<String> {
    let mut errors = ffi_calls
        .iter()
        .filter(|(instruction, contract)| *instruction != &contract.instruction)
        .map(|(instruction, contract)| {
            format!(
                "extern call FFI receipt key '{}' disagrees with receipt instruction '{}'",
                instruction, contract.instruction
            )
        })
        .collect::<Vec<_>>();
    let mut seen =
        BTreeMap::<MirInstructionId, (NodeId, NodeId, Vec<MirValueId>, Option<MirValueId>)>::new();
    for function in functions.values() {
        for block in function.blocks.values() {
            for instruction in &block.instructions {
                let MirInstructionKind::Call {
                    callee: ResolvedCallee::Extern(callee),
                    result,
                    arguments,
                    ..
                } = &instruction.kind
                else {
                    continue;
                };
                if let Some(previous_owner) = seen.insert(
                    instruction.id.clone(),
                    (
                        function.owner.clone(),
                        callee.clone(),
                        arguments.clone(),
                        result.clone(),
                    ),
                ) {
                    errors.push(format!(
                        "extern MIR call instruction '{}' appears in multiple functions ('{}' and '{}')",
                        instruction.id, previous_owner.0.0, function.owner.0
                    ));
                }
            }
        }
    }
    for (instruction, contract) in ffi_calls {
        if let Some((actual_caller, actual_callee, actual_arguments, actual_result)) =
            seen.get(instruction)
        {
            if contract.caller != *actual_caller {
                errors.push(format!(
                    "extern call FFI receipt caller '{}' disagrees with MIR instruction '{}' owner '{}'",
                    contract.caller.0, instruction, actual_caller.0
                ));
            }
            if contract.callee != *actual_callee {
                errors.push(format!(
                    "extern call FFI receipt callee '{}' disagrees with MIR instruction '{}' callee '{}'",
                    contract.callee.0, instruction, actual_callee.0
                ));
            }
            if contract.abi != "C" {
                errors.push(format!(
                    "extern call FFI receipt ABI '{}' is outside the canonical C ABI",
                    contract.abi
                ));
            }
            if let Err(message) = validate_ffi_symbol_manifest_safety(&contract.symbol) {
                errors.push(format!("extern call {message}"));
            } else {
                if let Err(message) =
                    validate_ffi_symbol_matches_callee(actual_callee, &contract.symbol)
                {
                    errors.push(message);
                }
            }
            if contract.arguments != *actual_arguments {
                errors.push(format!(
                    "extern call FFI receipt arguments disagree with MIR instruction '{}' arguments",
                    instruction
                ));
            }
            if contract.result != *actual_result {
                errors.push(format!(
                    "extern call FFI receipt result disagrees with MIR instruction '{}' result",
                    instruction
                ));
            }
            if actual_result
                .as_ref()
                .is_some_and(|result| actual_arguments.iter().any(|argument| argument == result))
            {
                errors.push(format!(
                    "extern MIR call instruction '{}' result identity overlaps an argument identity",
                    instruction
                ));
            }
            if actual_result.is_none() {
                errors.push(format!(
                    "extern MIR call instruction '{}' has no canonical result value identity",
                    instruction
                ));
            }
        }
    }
    errors.extend(
        seen.keys()
            .filter(|instruction| !ffi_calls.contains_key(*instruction))
            .map(|instruction| {
                format!(
                    "extern MIR call instruction '{}' has no FFI receipt",
                    instruction
                )
            })
            .collect::<Vec<_>>(),
    );
    errors.extend(
        ffi_calls
            .keys()
            .filter(|instruction| !seen.contains_key(*instruction))
            .map(|instruction| {
                format!(
                    "extern call FFI receipt '{}' is orphaned from a MIR extern call",
                    instruction
                )
            })
            .collect::<Vec<_>>(),
    );
    errors
}

const SCALAR_FFI_DEFERRED_REQUIRES_ERROR: &str =
    "extern requires Deferred contract is outside the executable scalar FFI route";
const SCALAR_FFI_DEFERRED_ENSURES_ERROR: &str =
    "extern ensures Deferred contract is outside the executable scalar FFI route";

/// Validate an executable-shaped scalar FFI call receipt for verifier-only
/// MIR proof consumers: enforces every `ScalarExecution` declaration, parameter
/// mode, witness, and endpoint invariant except the runtime prohibition on
/// IEEE-754 float contract leaves (modeled via `FullIeee754` in verifier passes).
pub(crate) fn validate_ffi_call_contract_scalar_verifier_receipt(
    type_catalog: &types::MirTypeCatalog,
    function: &MirFunction,
    instruction: &MirInstructionId,
    callee: &NodeId,
    result: Option<&MirValueId>,
    arguments: &[MirValueId],
    contract: &MirFfiCallContract,
) -> Vec<String> {
    let mut errors = validate_ffi_call_contract_receipt(
        type_catalog,
        function,
        instruction,
        callee,
        result,
        arguments,
        contract,
    );
    errors.retain(|message| {
        message != "extern requires float leaves are outside the runtime FFI predicate contract"
            && message
                != "extern ensures float leaves are outside the runtime FFI predicate contract"
            && message != SCALAR_FFI_DEFERRED_REQUIRES_ERROR
            && message != SCALAR_FFI_DEFERRED_ENSURES_ERROR
    });
    errors
}

/// Validate that every call-site using one C symbol agrees on its declared
/// ABI shape. A symbol has one physical declaration in native code and one
/// libffi call interface in bytecode; accepting divergent receipt declarations
/// would make route identity depend on the consumer that happens to run first.
pub(crate) fn validate_ffi_symbol_declaration_shapes(
    ffi_calls: &BTreeMap<MirInstructionId, MirFfiCallContract>,
) -> Vec<String> {
    let mut shapes =
        BTreeMap::<String, (usize, Vec<ResolvedTypeId>, ResolvedTypeId, String, bool)>::new();
    let mut errors = Vec::new();
    for contract in ffi_calls.values() {
        if validate_ffi_symbol_manifest_safety(&contract.symbol).is_err() {
            continue;
        }
        let shape = (
            contract.fixed_argument_count,
            contract
                .parameter_types
                .iter()
                .take(contract.fixed_argument_count)
                .cloned()
                .collect(),
            contract.result_type.clone(),
            contract.abi.clone(),
            contract.variadic,
        );
        if let Some(previous) = shapes.get(&contract.symbol) {
            if previous != &shape {
                errors.push(format!(
                    "FFI symbol '{}' is used with incompatible declaration TypeDescs or variadic ABI shape",
                    contract.symbol
                ));
            }
        } else {
            shapes.insert(contract.symbol.clone(), shape);
        }
    }
    errors
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum MirTerminator {
    Goto {
        edge: MirEdgeId,
        target: MirBlockId,
        arguments: Vec<MirValueId>,
    },
    Branch {
        condition: MirValueId,
        then_edge: MirEdgeId,
        then_target: MirBlockId,
        then_arguments: Vec<MirValueId>,
        else_edge: MirEdgeId,
        else_target: MirBlockId,
        else_arguments: Vec<MirValueId>,
    },
    Switch {
        scrutinee: MirValueId,
        arms: Vec<MirSwitchArm>,
    },
    /// Consume a non-Copy Option/Result scrutinee and route its active
    /// payload into the selected arm.  Unbound payload fields are released
    /// by the variant glue contract; bound fields become target block
    /// parameters.  This is deliberately distinct from Copy-only `Switch`.
    SwitchMove {
        scrutinee: MirValueId,
        arms: Vec<MirSwitchArm>,
    },
    Return {
        value: Option<MirValueId>,
    },
    Trap {
        code: String,
    },
    Fault {
        value: Option<MirValueId>,
    },
    Unreachable,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum MirSwitchCase {
    Literal(ResolvedLiteral),
    Variant(NodeId),
    Default,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MirSwitchArm {
    pub edge: MirEdgeId,
    pub target: MirBlockId,
    pub arguments: Vec<MirValueId>,
    /// Payloads projected from the selected variant into target block
    /// parameters. A default arm cannot contain bindings.
    pub bindings: Vec<MirSwitchBinding>,
    pub case: MirSwitchCase,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MirSwitchBinding {
    pub parameter: MirValueId,
    /// TypeDesc-owned proof of the payload projection. Canonical consumers
    /// must use this receipt; they may not reconstruct the variant field
    /// index, arity, or field type from a runtime tag or payload vector.
    pub projection: types::MirVariantProjectionContract,
    /// Optional second-stage tuple projection for the narrow consuming
    /// destructure shape. The outer variant field is moved once, then every
    /// tuple element is transferred to a distinct arm parameter.
    pub nested_tuple: Option<types::MirTupleProjectionContract>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MirBlock {
    pub id: MirBlockId,
    pub parameters: Vec<MirBlockParameter>,
    pub instructions: Vec<MirInstruction>,
    pub terminator: MirTerminator,
}

/// A concrete callable after frontend resolution but before a backend is
/// selected. values is a catalog, not an implicit vector index.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MirFunction {
    pub owner: NodeId,
    pub parameters: Vec<MirValueId>,
    /// Checker-owned parameter directions in declaration order. `Some` is
    /// required for production MIR; `None` is reserved for hand-built
    /// structural fixtures that do not carry a callable signature.
    pub parameter_permissions: Option<Vec<Option<crate::core::ir::Permission>>>,
    pub result: ResolvedTypeId,
    pub entry: MirBlockId,
    pub values: BTreeMap<MirValueId, MirValue>,
    pub blocks: BTreeMap<MirBlockId, MirBlock>,
    /// Canonical scalar contract predicates.  Conditions use MIR value
    /// identities rather than source expressions or display names.
    pub contracts: Vec<MirContract>,
    /// Ordered, checker-owned Math and stationary loop proof points. The
    /// expressions contain canonical MIR identities/TypeDesc paths, not a
    /// ResolvedBody or surface-AST node.
    pub proof_worklist: Option<MirProofWorklist>,
    /// Checker-owned resource facts projected into a backend-neutral event
    /// stream.  Consumers must use this stream together with TypeDesc rather
    /// than infer ownership from a physical register or pointer shape.
    pub ownership: MirOwnershipSummary,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum MirOwnershipEventKind {
    Read,
    Write,
    Introduce,
    Move,
    Drop,
    Return,
    TransferSession,
    TransferChild,
    BorrowShared,
    BorrowMut,
    BorrowEnd,
}

impl MirOwnershipEventKind {
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Read => "read",
            Self::Write => "write",
            Self::Introduce => "introduce",
            Self::Move => "move",
            Self::Drop => "drop",
            Self::Return => "return",
            Self::TransferSession => "transfer_session",
            Self::TransferChild => "transfer_child",
            Self::BorrowShared => "borrow_shared",
            Self::BorrowMut => "borrow_mut",
            Self::BorrowEnd => "borrow_end",
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MirOwnershipEvent {
    pub kind: MirOwnershipEventKind,
    pub resource: String,
    /// Stable value identity when the resource is backed by a MIR local.
    /// Synthetic discarded/session resources intentionally leave this empty.
    pub value: Option<MirValueId>,
    pub source: Option<String>,
    pub target: Option<String>,
    pub point: NodeId,
    /// Checker-stable identity shared by a borrow start and its end receipts.
    pub loan: Option<NodeId>,
    /// Original checker CFG location, retained as identity metadata. This is
    /// not a MIR block mapping and does not by itself prove path or timing.
    pub checker_block: Option<NodeId>,
    /// Original checker CFG edge for edge-specific loan ends.
    pub checker_edge: Option<NodeId>,
}

